/* HyperOS 4 web simulation. No framework, API key, or build step required. */
(() => {
'use strict';
const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const makeId = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const fmtTime = d => new Date(d).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',hour12:false});
const fmtDate = d => new Date(d).toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
const dateISO = (d=new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const todayISO = () => dateISO(new Date());
const WALLPAPERS = [
 'radial-gradient(ellipse at 15% 18%,rgba(255,255,255,.72) 0%,transparent 21%),radial-gradient(ellipse at 80% 24%,rgba(151,202,255,.85) 0%,transparent 33%),radial-gradient(ellipse at 65% 78%,rgba(164,131,255,.8) 0%,transparent 36%),linear-gradient(145deg,#15294e,#557fb8 42%,#2b3158)',
 'radial-gradient(ellipse at 20% 25%,#ffcba8 0%,transparent 28%),radial-gradient(ellipse at 76% 52%,#ff719e 0%,transparent 31%),radial-gradient(ellipse at 25% 90%,#553f9a 0%,transparent 44%),linear-gradient(135deg,#351d51,#a33e78 52%,#ed9569)',
 'radial-gradient(ellipse at 80% 12%,#c3f2db 0%,transparent 28%),radial-gradient(ellipse at 20% 60%,#70d4ce 0%,transparent 32%),radial-gradient(ellipse at 76% 83%,#81a3e6 0%,transparent 38%),linear-gradient(140deg,#112d4d,#267e96 54%,#315080)',
 'radial-gradient(ellipse at 72% 18%,#efedff 0%,transparent 22%),radial-gradient(ellipse at 26% 54%,#9b91ff 0%,transparent 40%),radial-gradient(ellipse at 70% 88%,#fa8fba 0%,transparent 33%),linear-gradient(145deg,#342b72,#7451a8 56%,#e2a1c7)',
 'radial-gradient(ellipse at 75% 14%,#fff4cb 0%,transparent 25%),radial-gradient(ellipse at 20% 68%,#ffcb74 0%,transparent 35%),linear-gradient(140deg,#3b3b66,#8b6388 56%,#db976f)',
 'radial-gradient(ellipse at 50% 8%,#bdd5e8 0%,transparent 28%),radial-gradient(ellipse at 65% 72%,#6a92ba 0%,transparent 42%),linear-gradient(150deg,#141d31,#354862 50%,#0f1729)'
];
const APPS = [
['phone','Телефон','☎','#55df98,#119d6d','Вызовы и набор номера','Связь'],['contacts','Контакты','♟','#79c6ff,#4577e8','Адресная книга','Связь'],['messages','Сообщения','▰','#7ee0ad,#36b875','Локальные переписки','Связь'],['browser','Браузер','◉','#7fd1ff,#3c75e8','Сайты и поиск в интернете','Интернет'],['camera','Камера','◎','#d7e0eb,#687c91','Фото и видео','Медиа'],['gallery','Галерея','▧','#ffdc8a,#ff7f76,#a86aff','Фото и альбомы','Медиа'],['music','Музыка','♫','#ff94be,#d84e91','Локальное аудио','Медиа'],['video','Видео','▶','#7898ff,#6f4ee8','Локальные видеозаписи','Медиа'],['settings','Настройки','⚙','#dce1eb,#8c96a8','Система и персонализация','Система'],['weather','Погода','☀','#84d9ff,#4b91ec','Прогноз из Open-Meteo','Инструменты'],['calendar','Календарь','▦','#fff,#f3e8e8','События и напоминания','Инструменты'],['clock','Часы','◷','#3e4c72,#121b38','Таймер, секундомер, будильники','Инструменты'],['calculator','Калькулятор','＋','#b5f2c7,#50be8a','Вычисления и история','Инструменты'],['notes','Заметки','▤','#fff2a7,#ffc85d','Текст и чек-листы','Инструменты'],['recorder','Диктофон','●','#ffa2b9,#e54e6b','Запись микрофона','Медиа'],['files','Проводник','▰','#ffdf83,#f1a943','Файлы прототипа','Система'],['downloads','Загрузки','↓','#a3d9ff,#4e8cda','Локальные загрузки','Система'],['themes','Темы','✿','#ffb4cf,#a36eff','Обои и акценты','Персонализация'],['security','Безопасность','⬡','#9be8c1,#39b58b','Разрешения симуляции','Система'],['tasks','Недавние','▢','#a9b8ce,#687e9f','Переключение приложений','Система'],['search','Поиск','⌕','#b2d8ff,#7b9ee6','Поиск по данным устройства','Система'],['store','Магазин','▣','#fac4a6,#f18d66','Каталог приложений симуляции','Инструменты'],['mail','Почта','✉','#b2c8ff,#597be7','Демонстрационные письма','Связь'],['health','Здоровье','♡','#ffb4c4,#f46f8d','Демонстрационная активность','Инструменты'],['games','Игры','◈','#c3a5ff,#7861de','Мини-игры и рекорды','Развлечения'],['help','Справка','?','#d1e4f5,#7aa7cb','Жесты, функции и ограничения','Система'],['update','Обновление','↻','#b1e4cf,#58b99a','Версия веб-симуляции','Система']
].map(([id,name,icon,colors,subtitle,category])=>({id,name,icon,colors,subtitle,category}));
const APP_BY_ID = Object.fromEntries(APPS.map(a=>[a.id,a]));
const dockIds = ['phone','messages','browser','camera'];
const wallpaperNames = ['Aurora','Bloom','Lagoon','Lavender','Sunset','Midnight'];
const defaultToggles = {wifi:true,bluetooth:true,airplane:false,flashlight:false,mobile:true,location:false,rotation:true,batterySaver:false,dark:false,silent:false,dnd:false,hotspot:false,screenRecord:false};
const CONTROL_TILES = [['wifi','◔','Wi-Fi'],['bluetooth','ᛒ','Bluetooth'],['airplane','✈','Режим полёта'],['mobile','▂','Мобильная сеть'],['location','⌖','Геолокация'],['rotation','⟳','Автоповорот'],['batterySaver','♧','Экономия'],['dark','◐','Тёмная тема'],['silent','♩','Без звука'],['dnd','☾','Не беспокоить'],['hotspot','⌁','Точка доступа'],['flashlight','☼','Фонарик'],['screenRecord','◉','Запись экрана']];
function defaults(){const tab=makeId();return {
 version:1,locked:true,pinMode:false,pinEntry:'',currentApp:null,panel:'none',page:0,contextMenu:null,folderViewer:null,folderModal:null,
 installed:APPS.map(a=>a.id),desktopItems:APPS.map(a=>a.id).filter(id=>!dockIds.includes(id)),folders:[],recents:[],
 settings:{dark:false,wallpaper:0,accent:'#8da8ff',brightness:92,volume:68,iconScale:1,textScale:1,animations:true,pin:'1234',lockClock:0,notifyByApp:{},hiddenTiles:[]},toggles:{...defaultToggles},
 notifications:[{id:'welcome',appId:'help',title:'Добро пожаловать',body:'Свайпните вниз справа для центра управления, слева для уведомлений.',at:Date.now(),read:false}],
 notes:[],contacts:[{id:'contact-demo-1',name:'Алексей',phone:'+7 900 000-00-01',email:'alex@example.test',favorite:true},{id:'contact-demo-2',name:'Мария',phone:'+7 900 000-00-02',email:'maria@example.test',favorite:false}],
 messages:[{id:'thread-demo-1',contactName:'Мария',phone:'+7 900 000-00-02',messages:[{id:'m1',from:'them',text:'Привет! Это локальная симуляция сообщений.',at:Date.now()-3600000}]}],calls:[],events:[],alarms:[],timerEndsAt:null,timerDuration:60,stopwatchElapsed:0,stopwatchRunningAt:null,
 browserTabs:[{id:tab,url:'https://example.com',history:['https://example.com'],index:0}],activeTabId:tab,browserHistory:[],bookmarks:[],media:[],downloads:[],filesFolders:[{id:'docs-root',name:'Документы',parent:null,createdAt:Date.now()},{id:'downloads-root',name:'Загрузки',parent:null,createdAt:Date.now()}],
 mailDrafts:[{id:'mail-demo-1',to:'demo@example.test',subject:'Добро пожаловать',body:'Это демонстрационное письмо. Оно не было отправлено.',sent:true,at:Date.now()-86400000}],emailRead:[],healthGoal:7000,gameScores:{},searchHistory:[],playingMediaId:null,mediaPlaying:false,
 ui:{section:'',query:'',selected:'',number:'',msgText:'',calculatorExpr:'',calculatorResult:'',city:'Moscow',timerInput:'60',alarmInput:'07:30',alarmLabel:'Будильник',eventTitle:'',eventDate:todayISO(),eventTime:'12:00',mailTo:'',mailSubject:'',mailBody:'',game:'tap',gameScore:0,newFolderName:'',fileFolder:null,fileFilter:'all',progress:0,stopwatchLap:[]}
};}
let state;try{const saved=JSON.parse(localStorage.getItem('hyperos4-state-v1')||'null');state=saved?deepMerge(defaults(),saved):defaults();}catch{state=defaults();}
function deepMerge(base,added){if(!added||typeof added!=='object')return base;for(const k of Object.keys(added)){if(base[k]&&typeof base[k]==='object'&&!Array.isArray(base[k])&&added[k]&&typeof added[k]==='object'&&!Array.isArray(added[k]))base[k]=deepMerge(base[k],added[k]);else base[k]=added[k];}return base;}
function persist(){try{const copy={...state};delete copy.contextMenu;delete copy.folderModal;localStorage.setItem('hyperos4-state-v1',JSON.stringify(copy));}catch(e){console.warn('Сохранение не удалось',e);toast('Не удалось сохранить данные. Возможно, хранилище заполнено.');}}
let persistTimer;function saveSoon(){clearTimeout(persistTimer);persistTimer=setTimeout(persist,130);}
const mediaURLs={};let weatherCache=null;let weatherLoading=false;let weatherError='';let weatherLastCity='';let cameraStream=null;let cameraRecorder=null;let cameraChunks=[];let micStream=null;let micRecorder=null;let micChunks=[];let micElapsed=0;let micTimer=null;let activeInterval=null;let lastAlarmMinute='';let audioRefs={};let lastTouch=null;let toastTimer=null;
const root=$('#app');

// IndexedDB stores binary assets; localStorage only stores metadata and system settings.
function dbOpen(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB unavailable'));return;}const r=indexedDB.open('hyperos4-media',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('media'))r.result.createObjectStore('media',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function loadMedia(){try{const db=await dbOpen();const rows=await new Promise((resolve,reject)=>{const r=db.transaction('media','readonly').objectStore('media').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error);});db.close();state.media=rows.map(({blob,...meta})=>{if(blob instanceof Blob&&!mediaURLs[meta.id])mediaURLs[meta.id]=URL.createObjectURL(blob);return meta;});persist();}catch(e){console.warn('Media store unavailable',e);}}
async function saveMedia(blob,name,kind){const item={id:`media-${makeId()}`,name,mime:blob.type||'application/octet-stream',kind,size:blob.size,createdAt:Date.now()};try{const db=await dbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').put({...item,blob});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();mediaURLs[item.id]=URL.createObjectURL(blob);state.media=[item,...state.media.filter(m=>m.id!==item.id)];saveSoon();toast('Файл сохранён в хранилище прототипа');render();return item;}catch(e){console.error(e);toast('Хранилище медиа недоступно');return null;}}
async function deleteMedia(id){try{const db=await dbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}catch{}if(mediaURLs[id]){URL.revokeObjectURL(mediaURLs[id]);delete mediaURLs[id];}state.media=state.media.filter(m=>m.id!==id);saveSoon();render();}
async function clearMedia(){try{const db=await dbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}catch{}Object.values(mediaURLs).forEach(URL.revokeObjectURL);Object.keys(mediaURLs).forEach(k=>delete mediaURLs[k]);state.media=[];}
function toast(msg){let el=$('.toast-message');if(!el){el=document.createElement('div');el.className='toast-message';root.appendChild(el);}el.textContent=msg;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(el.isConnected)el.remove();},2600);}
function appBy(id){return APP_BY_ID[id]||{id,name:id,icon:'?',colors:'#bbb,#888',subtitle:'',category:''};}
function appIcon(id,small=false,tiny=false){const a=appBy(id);const colors=a.colors.split(',');return `<span class="app-icon ${small?'small':''} ${tiny?'tiny':''}" style="background:linear-gradient(145deg,${colors.join(',')})"><span>${esc(a.icon)}</span><i></i></span>`;}
function addNotice(appId,title,body){if(state.settings.notifyByApp[appId]===false)return;state.notifications.unshift({id:makeId(),appId,title,body,at:Date.now(),read:false});state.notifications=state.notifications.slice(0,80);saveSoon();if(state.panel==='shade')render();}
function openApp(id){if(!state.installed.includes(id)&&!['settings','store'].includes(id)){toast('Приложение не установлено');return;}state.recents=[id,...state.recents.filter(x=>x!==id)].slice(0,8);state.currentApp=id;state.panel='none';state.folderViewer=null;state.contextMenu=null;state.ui.section='';state.ui.query='';state.ui.selected='';state.ui.contactEdit=null;state.ui.msgText='';persist();render();}
function goHome(){stopCamera();stopMic();state.currentApp=null;state.panel='none';state.folderViewer=null;state.contextMenu=null;saveSoon();render();}
function toggle(k){state.toggles[k]=!state.toggles[k];if(k==='dark')state.settings.dark=state.toggles[k];if(k==='screenRecord'&&state.toggles[k])addNotice('settings','Запись экрана','Запись имитируется внутри прототипа.');saveSoon();render();}
function statusBar(){return `<div class="status-bar" data-action="status-tap"><span class="status-time" data-clock>${fmtTime(Date.now())}</span><span class="status-notice-dots">${state.notifications.some(n=>!n.read)?'●':''}</span><div class="status-icons"><span class="${state.toggles.mobile?'':'muted'}">▂▄▆</span><span class="${state.toggles.wifi?'':'muted'}">◔</span><span class="${state.toggles.bluetooth?'':'muted'}">ᛒ</span><span class="battery">▰<i>${state.toggles.batterySaver?'⚡':'82'}</i></span></div></div>`;}
function hyperIsland(){const remain=state.timerEndsAt?Math.max(0,Math.ceil((state.timerEndsAt-Date.now())/1000)):0;const song=state.media.find(m=>m.id===state.playingMediaId);if(!state.timerEndsAt&&!state.mediaPlaying&&!state.toggles.screenRecord)return '';return `<button class="hyper-island ${state.panel==='island'?'expanded':''}" data-action="island"><span class="island-indicator">${state.mediaPlaying?'♫':state.toggles.screenRecord?'◉':'◷'}</span><span class="island-copy"><b>${state.mediaPlaying?esc(song?.name||'Музыка'):state.toggles.screenRecord?'Запись экрана':`Таймер · <span id="timer-remain">${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}</span>`}</b>${state.panel==='island'?`<small>${state.mediaPlaying?'Воспроизведение в симуляции':state.toggles.screenRecord?'Запись внутри прототипа':'Активная фоновая задача'}</small>`:''}</span>${state.mediaPlaying?`<span class="island-play" data-action="pause-music">Ⅱ</span>`:''}</button>`;}
function renderLock(){const time=fmtTime(Date.now()).split(':');const unread=state.notifications.find(n=>!n.read);return `<div class="lock-screen" style="background-image:${WALLPAPERS[state.settings.wallpaper%WALLPAPERS.length]}"><div class="lock-top"><span>${esc(fmtDate(Date.now()))}</span><span class="lock-weather" data-action="open-weather">Погода · прогноз</span></div><div class="lock-clock lock-clock-${state.settings.lockClock}"><div class="lock-time"><span>${time[0]}</span><span>:</span><span>${time[1]}</span></div><div class="lock-clock-sub">HYPEROS · PERSONAL SPACE</div></div><div class="lock-widget glass"><div class="lock-widget-icon">◷</div><div><b>${state.notifications.filter(n=>!n.read).length} уведомления</b><span>${esc(unread?.title||'Всё спокойно')}</span></div><div class="lock-widget-chev">›</div></div><div class="lock-bottom"><button class="lock-action" data-action="quick-lock">◉</button><button class="lock-action" data-action="launch-camera">◎</button></div>${state.pinMode?`<div class="pin-panel glass"><div class="pin-title">Введите PIN-код</div><div class="pin-dots">${[0,1,2,3].map(i=>`<span class="${state.pinEntry.length>i?'filled':''}"></span>`).join('')}</div><div class="pin-grid">${[1,2,3,4,5,6,7,8,9,'⌫',0,'✓'].map(n=>`<button data-action="pin-key" data-value="${n}">${n}</button>`).join('')}</div><button class="pin-cancel" data-action="pin-cancel">Отмена</button></div>`:''}<div class="unlock-hint"><span class="gesture-pill"></span><span>Свайп вверх для разблокировки</span><button data-action="pin-open">PIN-код</button><button data-action="unlock">Разблокировать</button></div></div>`;}
function renderHome(){const items=state.desktopItems.filter(it=>!it.startsWith('folder:')||state.folders.some(f=>`folder:${f.id}`===it));const pages=Math.max(1,Math.ceil(items.length/16));state.page=Math.max(0,Math.min(state.page,pages-1));const visible=items.slice(state.page*16,state.page*16+16);const desk=visible.map(item=>{if(item.startsWith('folder:')){const f=state.folders.find(x=>`folder:${x.id}`===item);if(!f)return '';return `<button class="desktop-item" data-action="open-folder" data-id="${f.id}" data-context="folder:${f.id}"><span class="folder-icon">${f.appIds.slice(0,4).map(a=>`<i style="background:linear-gradient(145deg,${appBy(a).colors})">${esc(appBy(a).icon)}</i>`).join('')}</span><span class="desktop-label">${esc(f.name)}</span></button>`;}const a=appBy(item);if(!a||!state.installed.includes(item))return '';return `<button class="desktop-item" data-action="open-app" data-id="${item}" data-context="app:${item}"><span style="transform:scale(${state.settings.iconScale})">${appIcon(item)}</span><span class="desktop-label">${esc(a.name)}</span></button>`;}).join('');
return `<div class="home-screen"><div class="home-top-row"><div class="home-date"><span>${new Date().toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'short'})}</span><b>${fmtTime(Date.now())}</b></div><button class="profile-orb" data-action="open-app" data-id="settings">◉</button></div><div class="home-widgets"><button class="weather-widget glass" data-action="open-weather"><div><span class="widget-overline">ПОГОДА · ${esc(state.ui.city||'МОСКВА').toUpperCase()}</span><b>${weatherCache&&weatherLastCity===state.ui.city?`${Math.round(weatherCache.temp)}°`:'—'}</b><small>${weatherCache&&weatherLastCity===state.ui.city?esc(weatherCache.text):'Загрузить актуальный прогноз'}</small></div><div class="weather-sun">☀</div></button><button class="calendar-widget glass" data-action="open-app" data-id="calendar"><div class="calendar-day">${new Date().getDate()}</div><div><span class="widget-overline">СЕГОДНЯ</span><b>${state.events.some(e=>e.date===todayISO())?'Есть события':'Планов пока нет'}</b><small>${new Date().toLocaleDateString('ru-RU',{weekday:'long'})}</small></div></button></div><button class="home-search glass" data-action="open-app" data-id="search"><span>⌕</span><span>Поиск приложений и контента</span><span class="search-spark">✦</span></button><div class="desktop-grid">${desk}</div><div class="home-page-dots">${Array.from({length:pages},(_,i)=>`<button class="${i===state.page?'active':''}" data-action="page" data-value="${i}"></button>`).join('')}</div><div class="dock-bar glass">${dockIds.map(id=>`<button data-action="open-app" data-id="${id}" aria-label="${appBy(id).name}">${appIcon(id,true)}</button>`).join('')}</div><div class="home-bottom"><button data-action="open-panel" data-value="recents">▱</button><button data-action="home" aria-label="Домой"><span></span></button><button data-action="open-panel" data-value="shade">‹</button></div></div>`;}
function renderPanel(){if(state.panel==='none')return '';if(state.panel==='control')return `<div class="panel-layer"><button class="panel-scrim" data-action="close-panel"></button><div class="control-panel glass-panel"><div class="panel-handle"></div><div class="control-head"><div><span>${esc(fmtDate(Date.now()))}</span><b>${fmtTime(Date.now())}</b></div><button data-action="open-app" data-id="settings">⚙</button></div><div class="quick-tiles">${CONTROL_TILES.filter(([k])=>!(state.settings.hiddenTiles||[]).includes(k)).map(([k,ico,label])=>`<button class="quick-tile ${state.toggles[k]?'on':''}" data-action="toggle" data-id="${k}"><span>${ico}</span><small>${label}</small></button>`).join('')}</div><div class="slider-block"><div><span>☼ Яркость</span><b>${state.settings.brightness}%</b></div><input type="range" min="10" max="100" value="${state.settings.brightness}" data-setting="brightness"></div><div class="slider-block"><div><span>♫ Громкость</span><b>${state.settings.volume}%</b></div><input type="range" min="0" max="100" value="${state.settings.volume}" data-setting="volume"></div><div class="control-footer"><span>Заряд · 82% (демо)</span><div><button data-action="edit-tiles">Изменить плитки</button><button data-action="open-app" data-id="settings">Настройки ›</button></div></div></div></div>`;
if(state.panel==='shade')return `<div class="panel-layer"><button class="panel-scrim" data-action="close-panel"></button><div class="shade-panel glass-panel"><div class="panel-handle"></div><div class="shade-head"><div><small>${esc(fmtDate(Date.now()))}</small><h2>Уведомления</h2></div><button data-action="read-all">✓</button></div><div class="notification-list">${state.notifications.length?state.notifications.map(n=>`<div class="notification-card ${n.read?'read':''}"><button class="notification-open" data-action="notification-open" data-id="${n.id}">${appIcon(n.appId,true,true)}<div><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small>${fmtTime(n.at)} · ${esc(appBy(n.appId).name)}</small></div></button><button class="notification-close" data-action="remove-notice" data-id="${n.id}">×</button></div>`).join(''):'<div class="empty-state">Пока тихо. Даже подозрительно.</div>'}</div>${state.notifications.length?'<button class="clear-notifications" data-action="clear-notices">Очистить все</button>':''}<button class="shade-settings" data-action="open-app" data-id="settings">⚙ Настройки уведомлений</button></div></div>`;
if(state.panel==='island')return `<div class="panel-layer"><button class="panel-scrim" data-action="close-panel"></button><div class="island-detail glass-panel"><div class="panel-handle"></div><h3>Активные задачи</h3>${state.timerEndsAt?`<div class="activity-row"><span class="activity-icon">◷</span><div><b>Таймер</b><small>Осталось ${Math.floor(Math.max(0,state.timerEndsAt-Date.now())/60000)} мин ${Math.floor(Math.max(0,state.timerEndsAt-Date.now())/1000)%60} сек</small></div><button data-action="stop-timer">×</button><button data-action="open-app" data-id="clock">Открыть</button></div>`:''}${state.mediaPlaying?`<div class="activity-row"><span class="activity-icon">♫</span><div><b>${esc(state.media.find(m=>m.id===state.playingMediaId)?.name||'Музыка')}</b><small>Воспроизведение в прототипе</small></div><button data-action="pause-music">Ⅱ</button><button data-action="open-app" data-id="music">Открыть</button></div>`:''}${state.toggles.screenRecord?`<div class="activity-row"><span class="activity-icon">◉</span><div><b>Запись экрана</b><small>Внутренняя имитация</small></div><button data-action="toggle" data-id="screenRecord">■ Стоп</button></div>`:''}</div></div>`;
if(state.panel==='editTiles')return `<div class="panel-layer"><button class="panel-scrim" data-action="close-panel"></button><div class="tile-edit-panel glass-panel"><div class="panel-handle"></div><h3>Плитки быстрого доступа</h3><p class="hint">Выберите, какие переключатели показывать в центре управления.</p><div class="tile-edit-list">${CONTROL_TILES.map(([k,ico,label])=>{const hidden=(state.settings.hiddenTiles||[]).includes(k);return `<div class="tile-edit-row"><div><b>${ico} ${label}</b><small>${hidden?'Скрыта из центра управления':'Отображается в центре управления'}</small></div><button data-action="tile-visibility" data-id="${k}">${hidden?'Добавить':'Скрыть'}</button></div>`;}).join('')}</div><button class="primary wide-button" data-action="close-panel">Готово</button></div></div>`;
if(state.panel==='recents')return `<div class="panel-layer"><button class="panel-scrim" data-action="close-panel"></button><div class="recents-panel glass-panel"><div class="panel-handle"></div><div class="recents-head"><b>Недавние приложения</b><button data-action="clear-recents">Очистить</button></div><div class="recents-grid">${state.recents.length?state.recents.map(id=>`<button data-action="open-app" data-id="${id}">${appIcon(id)}<span>${esc(appBy(id).name)}</span><i>↗</i></button>`).join(''):'<div class="empty-state">Здесь появятся открытые приложения</div>'}</div><button class="go-home-wide" data-action="home">⌂ На главный экран</button></div></div>`;
return '';
}
function topbar(id){const a=appBy(id);return `<div class="app-topbar"><button class="back-button" data-action="back">‹</button><div><h1>${esc(a.name)}</h1><small>${esc(a.subtitle)}</small></div>${id==='browser'?'<button class="topbar-action" data-action="new-tab">＋</button>':''}</div>`;}
function section(title,action='',label=''){return `<div class="section-title"><h2>${esc(title)}</h2>${action?`<button class="text-action" data-action="${action}">${label}</button>`:''}</div>`;}
function empty(text){return `<div class="empty-state">${esc(text)}</div>`;}
function searchInput(placeholder){return `<div class="app-search-field"><span>⌕</span><input data-search value="${esc(state.ui.query)}" placeholder="${esc(placeholder)}"><button data-action="clear-query">×</button></div>`;}
function toggleRow(key,title,sub,value){return `<div class="toggle-row"><div><b>${esc(title)}</b>${sub?`<small>${esc(sub)}</small>`:''}</div><button class="switch ${value?'on':''}" role="switch" aria-checked="${value}" data-action="setting-toggle" data-id="${key}"><i></i></button></div>`;}
function appContent(id){const u=state.ui;switch(id){
case 'phone':return `<div class="phone-tabs"><button class="${u.section===''?'selected':''}" data-action="section" data-value="">Клавиатура</button><button class="${u.section==='calls'?'selected':''}" data-action="section" data-value="calls">Недавние</button><button class="${u.section==='favorites'?'selected':''}" data-action="section" data-value="favorites">Избранное</button></div>${u.section==='calls'?`${section('История вызовов')}${state.calls.length?state.calls.map(c=>`<div class="list-row"><div class="round-mini">${c.type==='missed'?'↙':'↗'}</div><div class="row-main"><b>${esc(c.number)}</b><small>${fmtTime(c.at)} · ${c.type==='missed'?'Пропущенный':'Исходящий'} (симуляция)</small></div><button class="row-action" data-action="call-number" data-id="${esc(c.number)}">☎</button></div>`).join(''):empty('Вызовов пока нет')}`:u.section==='favorites'?state.contacts.filter(c=>c.favorite).map(c=>`<div class="list-row"><div class="contact-avatar">${esc(c.name[0])}</div><div class="row-main"><b>${esc(c.name)}</b><small>${esc(c.phone)}</small></div><button class="row-action" data-action="call-number" data-id="${esc(c.phone)}">☎</button></div>`).join(''):`<div class="dial-display">${esc(u.number)||'<span>Введите номер</span>'}</div><div class="dial-grid">${[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['*',''],['0','+'],['#','']].map(([n,l])=>`<button data-action="dial" data-value="${n}"><b>${n}</b><small>${l}</small></button>`).join('')}</div><div class="dial-actions"><button class="dial-call" data-action="call">☎</button><button data-action="dial-delete">⌫</button><button data-action="dial-clear">Очистить</button></div>`}`;
case 'contacts':return `${searchInput('Имя или номер')}<button class="primary wide-button" data-action="section" data-value="new-contact">＋ Новый контакт</button>${u.section==='new-contact'?`<form class="form-card" data-form="contact"><h3>${u.editingContact?'Редактировать контакт':'Новый контакт'}</h3><label>Имя<input name="name" value="${esc(u.contactDraft?.name||'')}" required></label><label>Телефон<input name="phone" value="${esc(u.contactDraft?.phone||'')}" type="tel"></label><label>Электронная почта<input name="email" value="${esc(u.contactDraft?.email||'')}" type="email"></label><div class="form-actions"><button type="button" data-action="section" data-value="">Отмена</button><button class="primary">Сохранить</button></div></form>`:state.contacts.filter(c=>`${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(u.query.toLowerCase())).map(c=>`<div class="list-row"><div class="contact-avatar">${esc(c.name.slice(0,1).toUpperCase())}</div><button class="row-main text-left" data-action="edit-contact" data-id="${c.id}"><b>${esc(c.name)}${c.favorite?' ★':''}</b><small>${esc(c.phone)}<br>${esc(c.email)}</small></button><button class="row-action" data-action="favorite-contact" data-id="${c.id}">★</button><button class="row-action" data-action="delete-contact" data-id="${c.id}">×</button></div>`).join('')}`;
case 'messages':{const t=state.messages.find(m=>m.id===u.activeThread);return u.section==='thread'&&t?`<button class="subtle-back" data-action="section" data-value="">‹ Все диалоги · ${esc(t.contactName)}</button><div class="message-thread">${t.messages.map(m=>`<div class="bubble ${m.from==='me'?'mine':''}"><p>${esc(m.text)}</p><small>${fmtTime(m.at)}</small></div>`).join('')}</div><form class="message-compose" data-form="message"><input name="text" value="${esc(u.msgText)}" placeholder="Сообщение в симуляции" required><button>➤</button></form>`:`${section('Сообщения','section-new-message','＋ Новое')}${u.section==='new-message'?`<form class="form-card" data-form="new-message"><label>Получатель (имя или номер)<input name="recipient" required></label><label>Первое сообщение<input name="text" required></label><button class="primary wide-button">Создать локальный диалог</button></form>`:''}${state.messages.map(m=>`<button class="conversation-row" data-action="open-thread" data-id="${m.id}"><div class="contact-avatar">${esc(m.contactName[0])}</div><div><b>${esc(m.contactName)}</b><p>${esc(m.messages.at(-1)?.text||'Нет сообщений')}</p><small>${m.messages.length?fmtTime(m.messages.at(-1).at):''}</small></div><span>›</span></button>`).join('')}`;}
case 'browser':{const tab=state.browserTabs.find(t=>t.id===state.activeTabId)||state.browserTabs[0];u.browserUrl??=tab.url;return `<div class="browser-address"><button data-action="browser-back" ${tab.index<=0?'disabled':''}>‹</button><button data-action="browser-forward" ${tab.index>=tab.history.length-1?'disabled':''}>›</button><form data-form="browser"><span>⌕</span><input name="url" value="${esc(u.browserUrl||tab.url)}" placeholder="Поиск или адрес сайта"><button type="submit">↻</button></form><button data-action="section" data-value="tabs">▢<small>${state.browserTabs.length}</small></button></div><div class="browser-quick"><button data-action="navigate" data-value="https://www.wikipedia.org">Wikipedia</button><button data-action="navigate" data-value="https://example.com">Example</button><button data-action="navigate" data-value="https://www.openstreetmap.org">OpenStreetMap</button><button data-action="section" data-value="history">История</button><button data-action="section" data-value="bookmarks">Закладки</button></div>${u.section==='tabs'?`<div class="browser-tabs-list">${state.browserTabs.map(t=>`<div class="browser-tab-card ${t.id===state.activeTabId?'active':''}"><button data-action="switch-tab" data-id="${t.id}"><b>${esc(safeHost(t.url))}</b><small>${esc(t.url)}</small></button><button data-action="close-tab" data-id="${t.id}">×</button></div>`).join('')}<button class="primary wide-button" data-action="new-tab">＋ Новая вкладка</button></div>`:u.section==='history'?`<div class="simple-list">${state.browserHistory.map(url=>`<button data-action="navigate" data-value="${esc(url)}"><b>${esc(url)}</b><small>Посещено ранее</small></button>`).join('')||empty('История пуста')}</div>`:u.section==='bookmarks'?`<div class="simple-list">${state.bookmarks.map(url=>`<button data-action="navigate" data-value="${esc(url)}"><b>${esc(url)}</b><small>Закладка</small></button>`).join('')||empty('Закладок пока нет')}</div>`:`<div class="browser-view"><div class="browser-start"><div class="browser-logo">◉</div><h2>Браузер</h2><p>Реальная веб-навигация с ограничениями iframe.</p><form class="browser-search-big" data-form="browser"><input name="url" value="${esc(u.browserUrl||tab.url)}" placeholder="Введите адрес или запрос"><button>→</button></form><div class="browser-tip"><b>Встроенный просмотр</b><span>Сайты могут запрещать iframe через CSP/X-Frame-Options. Для таких страниц нажмите «Открыть отдельно». Защита сайтов не обходится.</span></div></div><iframe key="${esc(tab.url)}" src="${esc(tab.url)}" title="Просмотр сайта" referrerpolicy="no-referrer" sandbox="allow-forms allow-scripts allow-same-origin allow-popups"></iframe><div class="browser-frame-actions"><button data-action="bookmark">☆ Закладка</button><a href="${esc(tab.url)}" target="_blank" rel="noreferrer">Открыть отдельно ↗</a><button data-action="copy-url">⧉ Копировать URL</button></div></div>`}`;}
case 'camera':return `<div class="camera-screen"><div class="camera-mode"><button class="${u.cameraMode!=='video'?'selected':''}" data-action="camera-mode" data-value="photo">Фото</button><button class="${u.cameraMode==='video'?'selected':''}" data-action="camera-mode" data-value="video">Видео</button></div><div class="camera-viewfinder"><video id="camera-feed" autoplay muted playsinline style="display:${u.cameraStatus==='live'?'block':'none'}"></video>${u.cameraStatus==='live'?'':`<div class="camera-placeholder"><span>◎</span><b>${u.cameraStatus==='denied'?'Камера недоступна':'Видоискатель'}</b><small>${u.cameraStatus==='denied'?'Разрешите доступ в настройках сайта или используйте демо-режим.':'Нажмите кнопку камеры, чтобы запросить явное разрешение браузера.'}</small><div class="camera-gridline"></div></div>`}<div class="camera-viewfinder-top"><span>HDR · AI</span><span>4:3 ▾</span></div></div><div class="camera-controls"><button data-action="camera-flip">⟳</button><button class="shutter" data-action="capture">●</button><button data-action="camera-start">◎</button></div>${u.cameraStatus!=='live'?`<div class="camera-lower-actions"><button class="primary" data-action="camera-start">Разрешить камеру</button><button data-action="camera-demo">Демо-режим</button></div>`:''}<p class="hint">Камера работает только после явного разрешения браузера. Демо-режим не создаёт поддельные фотографии.</p></div>`;
case 'gallery':{const ms=state.media.filter(m=>m.kind==='image');return `<div class="media-toolbar"><span>${ms.length} фото</span><label class="primary file-pick">＋ Импорт<input type="file" accept="image/*" multiple data-import="image"></label></div>${ms.length?`<div class="gallery-grid">${ms.map(m=>`<div class="gallery-item"><button data-action="view-media" data-id="${m.id}">${mediaURLs[m.id]?`<img src="${mediaURLs[m.id]}" alt="${esc(m.name)}">`:'▧'}</button><small>${esc(m.name)}</small><button class="delete-media" data-action="delete-media" data-id="${m.id}">×</button></div>`).join('')}</div>`:empty('Галерея пуста. Импортируйте изображения или сделайте снимок в Камере.')}${u.selected&&ms.some(m=>m.id===u.selected)?`<div class="media-viewer" data-action="close-viewer"><button data-action="close-viewer">×</button><img src="${mediaURLs[u.selected]||''}" alt="Просмотр фото"><span>${esc(ms.find(m=>m.id===u.selected).name)}</span></div>`:''}`;}
case 'music':{const ms=state.media.filter(m=>m.kind==='audio');return `<div class="music-hero"><div class="music-disc">♫</div><h2>${esc(state.media.find(m=>m.id===state.playingMediaId)?.name||'Ваша музыка')}</h2><p>Локальные аудиофайлы</p><label class="primary file-pick">＋ Добавить аудио<input type="file" accept="audio/*" multiple data-import="audio"></label></div>${ms.length?ms.map(m=>`<div class="track-row ${state.playingMediaId===m.id?'playing':''}"><button class="track-play" data-action="toggle-audio" data-id="${m.id}">${state.playingMediaId===m.id&&state.mediaPlaying?'Ⅱ':'▶'}</button><div><b>${esc(m.name)}</b><small>${(m.size/1024/1024).toFixed(1)} МБ · локальный файл</small>${mediaURLs[m.id]?`<audio controls preload="metadata" src="${mediaURLs[m.id]}" data-audio="${m.id}"></audio>`:''}</div><button data-action="delete-media" data-id="${m.id}">×</button></div>`).join(''):empty('Импортируйте собственные аудиофайлы. Музыка не предустановлена.')}`;}
case 'video':{const ms=state.media.filter(m=>m.kind==='video');return `<div class="media-toolbar"><span>Локальные видео</span><label class="primary file-pick">＋ Импорт<input type="file" accept="video/*" multiple data-import="video"></label></div>${ms.length?ms.map(m=>`<div class="video-card"><video controls src="${mediaURLs[m.id]||''}"></video><div><b>${esc(m.name)}</b><small>${(m.size/1024/1024).toFixed(1)} МБ</small><button data-action="delete-media" data-id="${m.id}">Удалить</button></div></div>`).join(''):empty('Добавьте локальный видеофайл для воспроизведения.')}`;}
case 'settings':return renderSettings();
case 'weather':return renderWeather();
case 'calendar':return `<div class="calendar-current"><div>${esc(new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</div><div class="calendar-week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7)+i);const iso=dateISO(d);return `<button class="${iso===u.eventDate?'today':''}" data-action="calendar-date" data-value="${iso}"><small>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</small><b>${d.getDate()}</b></button>`;}).join('')}</div></div><form class="form-card" data-form="event"><h3>Новое событие</h3><label>Название<input name="title" value="${esc(u.eventTitle)}" placeholder="Например, встреча" required></label><div class="two-fields"><label>Дата<input name="date" type="date" value="${esc(u.eventDate)}"></label><label>Время<input name="time" type="time" value="${esc(u.eventTime)}"></label></div><button class="primary wide-button">＋ Добавить событие</button></form>${section('События')}${state.events.length?state.events.map(ev=>`<div class="event-row"><div class="event-time"><b>${esc(ev.time)}</b><small>${esc(ev.date)}</small></div><div><b>${esc(ev.title)}</b><small>${ev.date===todayISO()?'Сегодня':'Запланировано'}</small></div><button data-action="edit-event" data-id="${ev.id}">✎</button><button data-action="delete-event" data-id="${ev.id}">×</button></div>`).join(''):empty('Событий пока нет')}`;
case 'clock':return `<div class="clock-current glass"><span>Текущее время</span><b data-clock-seconds>${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</b><small>${esc(fmtDate(Date.now()))}</small></div><div class="clock-tabs">${[['','Таймер'],['stopwatch','Секундомер'],['alarms','Будильник'],['world','Мировые часы']].map(([v,l])=>`<button class="${u.section===v?'selected':''}" data-action="section" data-value="${v}">${l}</button>`).join('')}</div>${u.section===''?`<div class="timer-card"><div class="timer-face"><span>◷</span><b id="clock-timer">${state.timerEndsAt?fmtRemaining(state.timerEndsAt-Date.now()):fmtSeconds(Number(u.timerInput)||60)}</b><small>${state.timerEndsAt?'ТАЙМЕР АКТИВЕН':'МИН : СЕК'}</small></div><label>Длительность в секундах<input data-ui="timerInput" type="number" min="1" max="86400" value="${esc(u.timerInput)}"></label><div class="form-actions"><button data-action="stop-timer">Сбросить</button><button class="primary" data-action="start-timer">▶ Запустить</button></div>${state.timerEndsAt?'<button class="text-action" data-action="stop-timer">Остановить таймер</button>':''}</div>`:u.section==='stopwatch'?`<div class="timer-card"><div class="timer-face"><span>⏱</span><b id="stopwatch-display">${fmtStopwatch(state.stopwatchElapsed+(state.stopwatchRunningAt?Date.now()-state.stopwatchRunningAt:0))}</b><small>СЕКУНДОМЕР</small></div><div class="form-actions"><button data-action="reset-stopwatch">Сбросить</button><button class="primary" data-action="toggle-stopwatch">${state.stopwatchRunningAt?'Ⅱ Пауза':'▶ Старт'}</button></div><div class="history-row">Отсчёт обновляется, пока вкладка открыта.</div></div>`:u.section==='alarms'?`<form class="form-card" data-form="alarm"><h3>Новый будильник</h3><div class="two-fields"><label>Время<input name="time" type="time" value="${esc(u.alarmInput)}"></label><label>Название<input name="label" value="${esc(u.alarmLabel)}"></label></div><button class="primary wide-button">Добавить</button></form>${state.alarms.map(a=>`<div class="alarm-row"><div><b>${esc(a.time)}</b><small>${esc(a.label)}</small></div>${toggleRow('alarm:'+a.id,'', '',a.enabled)}<button data-action="delete-alarm" data-id="${a.id}">×</button></div>`).join('')}`:`${[['Берлин','Europe/Berlin'],['Москва','Europe/Moscow'],['Токио','Asia/Tokyo'],['Нью-Йорк','America/New_York']].map(([n,z])=>`<div class="world-clock-row"><span>${n}</span><b>${new Intl.DateTimeFormat('ru-RU',{timeZone:z,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}</b></div>`).join('')}`}`;
case 'calculator':return `<div class="calculator"><div class="calc-history-preview">${esc(state.calcHistory?.slice(-2).join(' · ')||'')}</div><div class="calc-expression">${esc(u.calculatorExpr||'0')}</div><div class="calc-result">${esc(u.calculatorResult)}</div><div class="calc-grid">${['C','⌫','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','±','0','.','='].map(v=>`<button class="${['÷','×','−','+','='].includes(v)?'operator':''}" data-action="calc-key" data-value="${v}">${v}</button>`).join('')}</div></div>${section('История вычислений','clear-calc-history','Очистить')}${(state.calcHistory||[]).slice().reverse().map(x=>`<div class="history-row">${esc(x)}</div>`).join('')||empty('Результаты появятся здесь')}`;
case 'notes':{const notes=state.notes.filter(n=>`${n.title} ${n.body}`.toLowerCase().includes(u.query.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updatedAt-a.updatedAt);const selected=notes.find(n=>n.id===u.selected)||notes[0];return `<div class="notes-heading"><span>${state.notes.length} заметок</span><button class="primary" data-action="new-note">＋ Новая заметка</button></div>${searchInput('Поиск заметок')}<div class="notes-layout"><div class="note-list">${notes.map(n=>`<button class="note-list-item ${selected?.id===n.id?'selected':''}" data-action="select-note" data-id="${n.id}"><b>${esc(n.title||'Без названия')}</b><small>${esc(n.body||'Пустая заметка')}</small><i>${n.pinned?'📌 ':''}${fmtTime(n.updatedAt)}</i></button>`).join('')}</div>${selected?`<div class="note-editor" style="background:${selected.color}"><input data-note-title="${selected.id}" value="${esc(selected.title)}" placeholder="Заголовок"><textarea data-note-body="${selected.id}" placeholder="Начните писать…">${esc(selected.body)}</textarea><div><button data-action="pin-note" data-id="${selected.id}">${selected.pinned?'📌 Открепить':'📌 Закрепить'}</button><button data-action="delete-note" data-id="${selected.id}">Удалить</button></div></div>`:empty('Выберите или создайте заметку')}</div><p class="hint">Автосохранение в localStorage браузера.</p>`;}
case 'recorder':return renderRecorder();
case 'files':return renderFiles();
case 'downloads':return renderDownloads();
case 'themes':return renderThemes();
case 'security':return renderSecurity();
case 'tasks':return `${section('Недавние приложения','clear-recents','Очистить') }<div class="task-grid">${state.recents.filter(x=>x!=='tasks').map(id=>`<button data-action="open-app" data-id="${id}"><div class="task-preview" style="background:linear-gradient(145deg,${appBy(id).colors})">${esc(appBy(id).icon)}</div><b>${esc(appBy(id).name)}</b><span>Открыть ↗</span></button>`).join('')||empty('Здесь появятся открытые приложения')}</div><button class="primary wide-button" data-action="home">На рабочий стол</button><p class="hint">Это визуальный список, он не завершает процессы Android.</p>`;
case 'search':return renderSearch();
case 'store':return renderStore();
case 'mail':return renderMail();
case 'health':return renderHealth();
case 'games':return renderGames();
case 'help':return renderHelp();
case 'update':return renderUpdate();
default:return empty('Экран приложения недоступен');
}}
function renderApp(){const id=state.currentApp;return `<div class="app-shell ${state.settings.dark?'dark':''}"><div class="app-view app-${id}" style="--text-scale:${state.settings.textScale}">${topbar(id)}<div class="app-content">${appContent(id)}</div></div><div class="app-navigation"><button data-action="home"><span></span></button></div></div>`;}
function render(){document.body.classList.toggle('dark',state.settings.dark);root.innerHTML=`<div class="os-root ${state.settings.dark?'dark':''} ${state.settings.animations?'':'reduce-motion'}" style="--accent:${state.settings.accent};--text-scale:${state.settings.textScale}"><div class="wallpaper" style="background:${WALLPAPERS[state.settings.wallpaper%WALLPAPERS.length]};filter:${state.settings.dark?'brightness(.78) saturate(.88)':'none'}"><div class="wallpaper-orbit orbit-one"></div><div class="wallpaper-orbit orbit-two"></div><div class="wallpaper-grain"></div></div>${state.locked?renderLock():`${statusBar()}${hyperIsland()}${state.currentApp?renderApp():renderHome()}`}${renderPanel()}${renderModals()}<div class="brightness-overlay" style="opacity:${Math.max(0,(100-state.settings.brightness)/100)*.55}"></div></div>`;document.documentElement.style.setProperty('--text-scale',state.settings.textScale);}
function renderModals(){let html='';if(state.folderViewer){const f=state.folders.find(x=>x.id===state.folderViewer);html+=`<div class="modal-shade" data-action="close-folder"><div class="folder-modal glass-panel" data-stop><div class="modal-head"><h3>${esc(f?.name||'Папка')}</h3><button data-action="close-folder">×</button></div><div class="folder-app-grid">${(f?.appIds||[]).map(a=>`<button data-action="folder-open-app" data-id="${a}">${appIcon(a)}<span>${esc(appBy(a).name)}</span></button>`).join('')}</div></div></div>`;}if(state.folderModal){const item=state.folderModal;html+=`<div class="modal-shade" data-action="close-folder-modal"><div class="rename-modal glass-panel" data-stop><h3>Новая папка</h3><p>Приложение «${esc(appBy(item.appId).name)}» будет перемещено в папку.</p><input id="folder-name" value="${esc(item.value||'')}" placeholder="Название папки"><div class="modal-actions"><button data-action="close-folder-modal">Отмена</button><button class="primary" data-action="create-folder">Создать</button></div></div></div>`;}if(state.viewerId){const item=state.media.find(m=>m.id===state.viewerId);if(item)html+=`<div class="media-viewer" data-action="close-viewer"><button data-action="close-viewer">×</button><img src="${mediaURLs[item.id]||''}" alt="${esc(item.name)}"><span>${esc(item.name)}</span></div>`;}if(state.contextMenu){const cm=state.contextMenu;html+=`<div class="context-menu-backdrop" data-action="close-context"><div class="context-menu glass-panel" style="left:${cm.x}px;top:${cm.y}px" data-stop>${cm.kind==='app'?`<button data-action="open-app" data-id="${cm.id}">Открыть</button><button data-action="folder-modal" data-id="${cm.id}">Создать папку</button><button data-action="remove-desktop" data-id="${cm.id}">Убрать с экрана</button>`:`<button data-action="rename-folder" data-id="${cm.id}">Переименовать</button><button data-action="delete-folder" data-id="${cm.id}">Удалить папку</button>`}</div></div>`;}return html;}
function safeHost(u){try{return new URL(u).hostname;}catch{return u;}}
function fmtSeconds(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function fmtRemaining(ms){return fmtSeconds(Math.ceil(Math.max(0,ms)/1000));}
function fmtStopwatch(ms){return `${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(Math.floor(ms%1000/10)).padStart(2,'0')}`;}
function calc(expression){let s=expression.replace(/×/g,'*').replace(/÷/g,'/').replace(/,/g,'.').replace(/%/g,'/100'),i=0;function ws(){while(/\s/.test(s[i]||''))i++;}function factor(){ws();if(s[i]==='+'){i++;return factor();}if(s[i]==='-'){i++;return-factor();}if(s[i]==='('){i++;const x=expr();ws();if(s[i]!==')')throw Error('Нужна закрывающая скобка');i++;return x;}const st=i;while(/[\d.]/.test(s[i]||''))i++;if(st===i)throw Error('Ожидалось число');const a=s.slice(st,i);if((a.match(/\./g)||[]).length>1)throw Error('Неверное число');return Number(a);}function term(){let x=factor();while(1){ws();if(s[i]==='*'){i++;x*=factor();}else if(s[i]==='/'){i++;const y=factor();if(!y)throw Error('Деление на ноль');x/=y;}else break;}return x;}function expr(){let x=term();while(1){ws();if(s[i]==='+'){i++;x+=term();}else if(s[i]==='-'){i++;x-=term();}else break;}return x;}if(!s.trim())throw Error('Введите выражение');const x=expr();ws();if(i<s.length||!Number.isFinite(x))throw Error('Проверьте выражение');return String(Number(x.toPrecision(12)));}
function renderSettings(){const sec=state.ui.section;const q=state.ui.query.toLowerCase();if(!sec){return `${searchInput('Поиск по настройкам')}<div class="settings-profile glass"><div class="profile-avatar">●</div><div><b>HyperOS · Веб-симуляция</b><small>HyperOS 4 visual concept · 0.1.0</small></div><span>›</span></div>${[['appearance','Обои и персонализация','Темы, иконки, рабочий стол','✿'],['display','Дисплей','Яркость, тема и размер текста','☼'],['sound','Звук и вибрация','Громкость, тихий режим','♫'],['notifications','Уведомления','Управление уведомлениями приложений','▣'],['apps','Приложения','Установленные приложения','◈'],['battery','Батарея','Состояние симулируется','▰'],['storage','Хранилище','Файлы и медиа прототипа','▤'],['privacy','Конфиденциальность','Разрешения веб-симуляции','⬡'],['system','Система','Язык, время, жесты, блокировка','⚙'],['about','О системе','Сведения и сброс данных','ⓘ']].filter(x=>x.slice(1,3).join(' ').toLowerCase().includes(q)).map(([key,n,sub,ico])=>`<button class="settings-row" data-action="section" data-value="${key}"><span class="settings-ico">${ico}</span><span><b>${n}</b><small>${sub}</small></span><span class="chev">›</span></button>`).join('')}`;}
let html=`<button class="subtle-back" data-action="section" data-value="">‹ Все настройки</button>`;
switch(sec){case 'appearance':html+=`${section('Оформление')}<div class="wallpaper-grid">${wallpaperNames.map((n,i)=>`<button class="${state.settings.wallpaper===i?'selected':''}" data-action="wallpaper" data-value="${i}"><span style="background:${WALLPAPERS[i]}"></span><small>${n}</small></button>`).join('')}</div>${section('Размер значков')}<div class="inline-setting"><span>Масштаб</span><input type="range" min=".8" max="1.2" step=".05" value="${state.settings.iconScale}" data-setting="iconScale"><b>${Math.round(state.settings.iconScale*100)}%</b></div><button class="settings-row" data-action="open-app" data-id="themes"><span class="settings-ico">✿</span><span><b>Расширенные темы</b><small>Цвета, фон и визуальные эффекты</small></span><span>›</span></button>`;break;
case 'display':html+=`${section('Дисплей')}<div class="inline-setting"><span>Яркость</span><input type="range" min="10" max="100" value="${state.settings.brightness}" data-setting="brightness"><b>${state.settings.brightness}%</b></div>${toggleRow('dark','Тёмная тема','Применить ко всей симуляции',state.settings.dark)}<div class="inline-setting"><span>Размер текста</span><input type="range" min=".85" max="1.2" step=".05" value="${state.settings.textScale}" data-setting="textScale"><b>${Math.round(state.settings.textScale*100)}%</b></div>${toggleRow('animations','Плавные анимации','Учитывает reduced motion',state.settings.animations)}`;break;
case 'sound':html+=`${section('Звук')}<div class="inline-setting"><span>Громкость медиа</span><input type="range" min="0" max="100" value="${state.settings.volume}" data-setting="volume"><b>${state.settings.volume}%</b></div>${toggleRow('silent','Без звука','Внутренний переключатель',state.toggles.silent)}${toggleRow('dnd','Не беспокоить','Внутренний переключатель',state.toggles.dnd)}`;break;
case 'notifications':html+=`${section('Уведомления приложений')}${APPS.filter(a=>state.installed.includes(a.id)).map(a=>toggleRow('notify:'+a.id,a.name,'Уведомления внутри симуляции',state.settings.notifyByApp[a.id]!==false)).join('')}`;break;
case 'apps':html+=`${section('Установленные приложения')}${APPS.map(a=>`<div class="settings-row"><span class="settings-ico">${a.icon}</span><span><b>${a.name}</b><small>${state.installed.includes(a.id)?'Установлено':'Не установлено'}</small></span><button class="text-action" data-action="install-app" data-id="${a.id}">${state.installed.includes(a.id)?'Убрать':'Установить'}</button></div>`).join('')}`;break;
case 'battery':html+=`${section('Батарея')}<div class="battery-large"><span>▰</span><b>82%</b><small>Уровень демонстрационный</small></div>${toggleRow('batterySaver','Экономия энергии','Переключатель симуляции',state.toggles.batterySaver)}<p class="hint">Веб-страница не может читать реальное состояние батареи Android.</p>`;break;
case 'storage':html+=`${section('Хранилище прототипа')}<div class="storage-card"><div><b>${(state.media.reduce((a,m)=>a+m.size,0)/1048576).toFixed(1)} МБ</b><small>Импортированные медиафайлы</small></div><div class="storage-bar"><span style="width:${Math.min(100,state.media.reduce((a,m)=>a+m.size,0)/524288000*100)}%"></span></div><small>${state.media.length} объектов в IndexedDB</small></div><button class="settings-row" data-action="open-app" data-id="files"><span class="settings-ico">▰</span><span><b>Открыть проводник</b><small>Управление файлами прототипа</small></span><span>›</span></button>`;break;
case 'privacy':html+=`${section('Конфиденциальность')}<p class="hint">Эти переключатели относятся только к симуляции. Камера и микрофон дополнительно требуют разрешение браузера.</p>${[['camera','Камера'],['microphone','Микрофон'],['notifications','Уведомления'],['geolocation','Геолокация'],['files','Импорт файлов']].map(([id,n])=>toggleRow('perm:'+id,n,'Разрешение внутри прототипа',state.settings.notifyByApp['perm:'+id]!==false)).join('')}`;break;
case 'system':html+=`${section('Система')}<div class="simple-list"><button data-action="toast" data-value="Язык: Русский">Язык <small>Русский</small></button><button data-action="toast" data-value="Время берётся из браузера">Дата и время <small>Системное время браузера</small></button><button data-action="clock-style">Стиль часов блокировки <small>Нажмите, чтобы переключить</small></button><button data-action="change-pin">PIN-код симуляции <small>Изменить код</small></button><button data-action="show-gestures">Жесты <small>Подсказка по управлению</small></button></div>`;break;
case 'about':html+=`<div class="about-hero"><b>HyperOS 4</b><span>WEB SIMULATION</span><small>Концептуальная реконструкция</small></div><div class="simple-list"><button>Устройство <small>Browser Runtime · Android-friendly</small></button><button>Сборка <small>0.1.0-dev · октябрь 2026</small></button><button data-action="open-app" data-id="update">Обновление системы <small>История изменений</small></button><button class="danger-row" data-action="reset">Сбросить данные прототипа <small>Очистит localStorage и IndexedDB</small></button></div>`;break;
default:html+=empty('Раздел настроек не найден');}
return html;}
async function loadWeather(city){if(weatherLoading)return;if(weatherCache&&weatherLastCity.toLowerCase()===city.toLowerCase()){render();return;}weatherLoading=true;weatherError='';render();try{const g=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=ru&format=json`);if(!g.ok)throw Error('Сервис геокодирования недоступен');const gj=await g.json(),place=gj.results?.[0];if(!place)throw Error('Город не найден');const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,precipitation_probability&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=5&timezone=auto`);if(!r.ok)throw Error('Источник прогноза не ответил');const d=await r.json();weatherCache={temp:d.current.temperature_2m,humidity:d.current.relative_humidity_2m,wind:d.current.wind_speed_10m,code:d.current.weather_code,text:weatherDesc(d.current.weather_code),hours:d.hourly.time.slice(0,12).map((t,i)=>({time:t.slice(11,16),temp:d.hourly.temperature_2m[i],precip:d.hourly.precipitation_probability[i]})),days:d.daily.time.map((date,i)=>({date,max:d.daily.temperature_2m_max[i],min:d.daily.temperature_2m_min[i],code:d.daily.weather_code[i],rain:d.daily.precipitation_probability_max[i]}))};weatherLastCity=city;weatherError='';}catch(e){weatherError=e.message||'Не удалось загрузить прогноз';}finally{weatherLoading=false;if(state.currentApp==='weather')render();}}
function weatherDesc(c){if(c===0)return'Ясно';if(c<=3)return'Облачно';if(c<=48)return'Туман';if(c<=67)return'Дождь';if(c<=77)return'Снег';if(c>=95)return'Гроза';return'Осадки';}
function renderWeather(){if(!weatherLoading&&!weatherCache&& !weatherError)loadWeather(state.ui.city||'Moscow');return `<form class="weather-search" data-form="weather"><span>⌕</span><input name="city" value="${esc(state.ui.city||'Moscow')}" placeholder="Введите город"><button>Обновить</button></form>${weatherLoading?'<div class="loading-state">Загружаю реальный прогноз…</div>':weatherError?`<div class="weather-error"><b>Не удалось получить прогноз</b><p>${esc(weatherError)}</p><small>Нужен доступ к интернету. Выдуманные данные не подставляются.</small><button class="primary" data-action="retry-weather">Повторить</button></div>`:weatherCache?`<div class="weather-main glass"><span class="weather-current-icon">${weatherCache.code===0?'☀':'☁'}</span><div class="weather-location">${esc(weatherLastCity)}</div><div class="weather-temp">${Math.round(weatherCache.temp)}°</div><div class="weather-desc">${weatherCache.text}</div><div class="weather-stats"><span>Влажность <b>${weatherCache.humidity}%</b></span><span>Ветер <b>${weatherCache.wind} км/ч</b></span></div></div>${section('Почасовой прогноз')}<div class="hourly-weather">${weatherCache.hours.filter((_,i)=>i%2===0).slice(0,6).map(h=>`<div><small>${h.time}</small><b>${Math.round(h.temp)}°</b><span>☀</span><small>Дождь ${h.precip}%</small></div>`).join('')}</div>${section('На 5 дней')}${weatherCache.days.map(d=>`<div class="forecast-row"><span>${new Date(d.date+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'short'})}</span><b>${weatherDesc(d.code)}</b><small>Осадки ${d.rain}%</small><strong>${Math.round(d.max)}° / ${Math.round(d.min)}°</strong></div>`).join('')}<p class="hint">Источник: Open-Meteo. Город вводится вручную, геолокация не запрашивается.</p>`:''}`;}
function renderRecorder(){const ms=state.media.filter(m=>m.kind==='recording');return `<div class="recorder-screen"><div class="recorder-orb ${state.recorderStatus==='recording'?'recording':''}">●</div><b class="recorder-timer">${fmtSeconds(micElapsed)}</b><p>${state.recorderStatus==='recording'?'Идёт запись…':state.recorderStatus==='denied'?'Микрофон недоступен':'Готов к записи'}</p><button class="${state.recorderStatus==='recording'?'stop-record':'primary'}" data-action="${state.recorderStatus==='recording'?'stop-recorder':'start-recorder'}">${state.recorderStatus==='recording'?'■ Остановить запись':'● Начать запись'}</button>${section('Записи')}${ms.length?ms.map(m=>`<div class="list-row"><span class="file-type-icon">♫</span><div class="row-main"><b>${esc(m.name)}</b><small>${(m.size/1024).toFixed(0)} КБ</small>${mediaURLs[m.id]?`<audio controls src="${mediaURLs[m.id]}"></audio>`:''}</div><button data-action="delete-media" data-id="${m.id}">×</button></div>`).join(''):empty('Записей пока нет')}<p class="hint">Микрофон используется только после нажатия кнопки записи и разрешения браузера.</p></div>`;}
function renderFiles(){const u=state.ui;const ms=state.media.filter(m=>u.fileFilter==='all'||m.kind===u.fileFilter);return `<div class="file-tabs">${[['all','Все'],['image','Фото'],['audio','Аудио'],['video','Видео'],['file','Файлы']].map(([v,l])=>`<button class="${u.fileFilter===v?'selected':''}" data-action="file-filter" data-value="${v}">${l}</button>`).join('')}</div><div class="file-actions"><label class="primary file-pick">＋ Импорт файлов<input type="file" multiple data-import="file"></label><button data-action="section" data-value="new-folder">＋ Папка</button></div>${u.section==='new-folder'?`<form class="inline-create" data-form="file-folder"><input name="name" value="${esc(u.newFolderName)}" placeholder="Название папки"><button class="primary">Создать</button></form>`:''}${u.fileFolder?`<button class="subtle-back" data-action="folder-up">‹ Назад</button>`:''}${state.filesFolders.filter(f=>f.parent===u.fileFolder).map(f=>`<div class="list-row"><span class="file-type-icon">📁</span><button class="row-main text-left" data-action="open-files-folder" data-id="${f.id}"><b>${esc(f.name)}</b><small>Папка</small></button><button data-action="delete-files-folder" data-id="${f.id}">×</button></div>`).join('')}${ms.map(m=>`<div class="list-row"><span class="file-type-icon">${m.kind==='image'?'▧':m.kind==='audio'?'♫':m.kind==='video'?'▶':'▤'}</span><div class="row-main"><b>${esc(m.name)}</b><small>${m.kind} · ${(m.size/1024).toFixed(0)} КБ</small></div>${mediaURLs[m.id]?`<a class="row-action" href="${mediaURLs[m.id]}" download="${esc(m.name)}">↓</a>`:''}<button data-action="delete-media" data-id="${m.id}">×</button></div>`).join('')}<p class="hint">Проводник показывает только файлы, импортированные в прототип. Доступа ко всей файловой системе Android нет.</p>`;}
function renderDownloads(){return `<div class="download-head"><div><b>Загрузки</b><small>Изолированное хранилище браузера</small></div><label class="primary file-pick">＋ Импорт<input type="file" multiple data-import="file"></label></div>${state.downloads.map(d=>`<div class="download-card"><span class="download-icon">↓</span><div><b>${esc(d.name)}</b><small>${esc(d.url)}</small><div class="download-progress"><span style="width:${d.progress}%"></span></div><small>${d.status==='done'?'Завершено':d.status==='error'?'Ошибка загрузки':d.progress+'%'}</small></div><button data-action="delete-download" data-id="${d.id}">×</button></div>`).join('')}${state.media.filter(m=>m.kind==='file').map(m=>`<div class="download-card"><span class="download-icon">↓</span><div><b>${esc(m.name)}</b><small>${(m.size/1024).toFixed(0)} КБ · локальный файл</small></div><a href="${mediaURLs[m.id]}" download="${esc(m.name)}">Скачать ↗</a><button data-action="delete-media" data-id="${m.id}">×</button></div>`).join('')||(!state.downloads.length?empty('Загрузки пусты. Импортируйте файл, чтобы добавить его в хранилище.'):'')}`;}
function renderThemes(){return `${section('Обои рабочего стола')}<div class="theme-wallpapers">${wallpaperNames.map((n,i)=>`<button class="${state.settings.wallpaper===i?'selected':''}" data-action="wallpaper" data-value="${i}"><span style="background:${WALLPAPERS[i]}"></span><b>${n}</b>${state.settings.wallpaper===i?'<i>✓</i>':''}</button>`).join('')}</div>${section('Цвет оформления')}<div class="accent-choices">${['#8da8ff','#76dfb4','#ff9dba','#ffc36d','#c8a3ff','#7ed8ee'].map(c=>`<button style="background:${c}" class="${state.settings.accent===c?'selected':''}" data-action="accent" data-value="${c}"></button>`).join('')}</div>${toggleRow('dark','Тёмная тема','Применить глобально',state.settings.dark)}<button class="primary wide-button" data-action="toast" data-value="Тема применена без перезагрузки">Применить оформление</button>`;}
function renderSecurity(){return `<div class="security-hero glass"><span>⬡</span><b>Защита симуляции</b><small>Локальные данные хранятся в браузере</small><div class="security-meter"><i></i></div><p>Реальное устройство не сканируется, вирусы не ищутся.</p></div>${section('Разрешения внутри прототипа')}${[['perm:camera','Камера'],['perm:microphone','Микрофон'],['perm:location','Геолокация'],['perm:notifications','Уведомления'],['perm:files','Импорт файлов']].map(([k,n])=>toggleRow(k,n,'Симулированный контроль доступа',state.settings.notifyByApp[k]!==false)).join('')}${section('Системные переключатели')}<div class="security-states">${Object.entries(state.toggles).map(([k,v])=>`<span class="${v?'on':''}">${k}: ${v?'вкл':'выкл'}</span>`).join('')}</div>`;}
function renderSearch(){const q=state.ui.query.toLowerCase();if(!q)return `<div class="device-search-large"><span>⌕</span><input data-search value="" placeholder="Поиск по устройству"><button data-action="clear-query">×</button></div>${section('Быстрые действия')}<div class="quick-action-grid"><button data-action="open-app" data-id="settings">⚙<span>Настройки</span></button><button data-action="open-app" data-id="clock">◷<span>Таймер</span></button><button data-action="open-app" data-id="notes">▤<span>Заметка</span></button><button data-action="open-app" data-id="browser">◉<span>Интернет</span></button></div>${section('Недавний поиск')}${state.searchHistory.slice(0,5).map(q=>`<button class="search-history-row" data-action="search-history" data-value="${esc(q)}">⌕ ${esc(q)}</button>`).join('')}`;const apps=APPS.filter(a=>state.installed.includes(a.id)&&a.name.toLowerCase().includes(q));const contacts=state.contacts.filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(q));const notes=state.notes.filter(n=>`${n.title} ${n.body}`.toLowerCase().includes(q));const media=state.media.filter(m=>m.name.toLowerCase().includes(q));return `<div class="device-search-large"><span>⌕</span><input data-search value="${esc(state.ui.query)}" placeholder="Поиск по устройству"><button data-action="clear-query">×</button></div>${section('Приложения')}${apps.map(a=>`<button class="search-result" data-action="open-app" data-id="${a.id}"><span class="settings-ico">${a.icon}</span><span><b>${a.name}</b><small>Приложение</small></span><span>›</span></button>`).join('')||empty('Приложения не найдены')}${section('Контакты')}${contacts.map(c=>`<div class="search-result"><span class="settings-ico">♟</span><span><b>${esc(c.name)}</b><small>${esc(c.phone)}</small></span></div>`).join('')}${section('Заметки')}${notes.map(n=>`<button class="search-result" data-action="open-app" data-id="notes"><span class="settings-ico">▤</span><span><b>${esc(n.title)}</b><small>${esc(n.body.slice(0,80))}</small></span></button>`).join('')}${section('Файлы')}${media.map(m=>`<button class="search-result" data-action="open-app" data-id="${m.kind==='image'?'gallery':m.kind==='audio'?'music':'files'}"><span class="settings-ico">▤</span><span><b>${esc(m.name)}</b><small>${m.kind}</small></span></button>`).join('')}`;}
function renderStore(){return `<div class="store-banner"><span>▣</span><div><b>Каталог приложений</b><small>Установка только внутри симуляции</small></div></div>${searchInput('Поиск каталога')}${['Связь','Медиа','Инструменты','Система','Персонализация','Развлечения'].map(cat=>`${section(cat)}${APPS.filter(a=>a.category===cat&&a.name.toLowerCase().includes(state.ui.query.toLowerCase())).map(a=>`<div class="store-app-row"><span class="store-icon" style="background:linear-gradient(145deg,${a.colors})">${a.icon}</span><div><b>${a.name}</b><small>${a.subtitle}</small></div><button class="${state.installed.includes(a.id)?'installed-pill':'primary'}" data-action="install-app" data-id="${a.id}">${state.installed.includes(a.id)?'Открыть':'Установить'}</button></div>`).join('')}`).join('')}<p class="hint">Нельзя устанавливать APK, обращаться к системным пакетам Android или изменять настоящую прошивку.</p>`;}
function renderMail(){return `<div class="mail-toolbar"><div><b>Входящие</b><small>demo@example.test · локальная почта</small></div><button class="primary" data-action="section" data-value="compose">＋ Написать</button></div>${state.ui.section==='compose'?`<form class="form-card" data-form="mail"><h3>Новое письмо</h3><label>Кому<input name="to" value="${esc(state.ui.mailTo)}" required placeholder="name@example.com"></label><label>Тема<input name="subject" value="${esc(state.ui.mailSubject)}"></label><label>Сообщение<textarea name="body">${esc(state.ui.mailBody)}</textarea></label><div class="form-actions"><button type="button" data-action="section" data-value="">Отмена</button><button class="primary">Сохранить черновик</button></div></form>`:''}${section('Письма')}${state.mailDrafts.map(m=>`<div class="mail-row"><div class="mail-avatar">${esc((m.to||'D')[0].toUpperCase())}</div><div><b>${esc(m.subject||'(без темы)')}</b><small>${m.sent?'Демонстрационное письмо':'Черновик'} · ${esc(m.to)}</small><p>${esc(m.body.slice(0,100))}</p><small>${m.sent?'Это тестовое письмо, оно не было получено извне.':'Черновик не отправлен.'}</small></div><button data-action="delete-mail" data-id="${m.id}">×</button></div>`).join('')}<p class="hint">Для реальной отправки нужен подключённый почтовый сервис. Здесь все письма локальные.</p>`;}
function renderHealth(){return `<div class="health-hero glass"><span>♡</span><b>Сегодня</b><small>Учебные показатели, не датчики телефона</small><div class="health-steps">3 842 <small>шагов · демонстрация</small></div><div class="health-progress"><span style="width:${Math.min(100,3842/state.healthGoal*100)}%"></span></div><p>Цель: ${state.healthGoal.toLocaleString('ru-RU')} шагов</p><label>Изменить цель <input type="range" min="1000" max="15000" step="500" value="${state.healthGoal}" data-setting="healthGoal"></label></div>${section('Активность за неделю')}<div class="health-bars">${[30,54,42,79,62,36,51].map((v,i)=>`<div><span style="height:${v}%"></span><small>${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][i]}</small></div>`).join('')}</div><div class="health-stat-grid"><div><small>Активные минуты</small><b>24</b><span>демо</span></div><div><small>Дистанция</small><b>2,8 км</b><span>демо</span></div><div><small>Сон</small><b>7 ч 20 м</b><span>демо</span></div></div><p class="hint">Показатели демонстрационные, не считываются с датчиков.</p>`;}
function renderGames(){const g=state.ui.game||'tap';return `${section('Мини-игры')}<div class="game-chooser">${[['tap','Реакция'],['memory','Запомни'],['math','Счёт в уме']].map(([k,n])=>`<button class="${g===k?'selected':''}" data-action="game-select" data-value="${k}">${n}</button>`).join('')}</div>${g==='tap'?`<div class="game-card"><span>✦</span><h2>Тап-челлендж</h2><p>Нажимайте на цель, чтобы набирать очки.</p><button class="game-target" data-action="game-tap">✦</button><b>Очки: ${state.ui.gameScore||0}</b><small>Рекорд: ${state.gameScores.tap||0}</small></div>`:g==='memory'?`<div class="game-card"><h2>Запомни число</h2><p>Посмотрите на последовательность, затем повторите её по памяти. Раунд упрощён: выберите число, показанное в задании.</p><div class="math-question">${state.ui.memoryTarget??'3'}</div><div class="memory-grid">${[1,2,3,4].map(n=>`<button data-action="memory-answer" data-value="${n}">${n}</button>`).join('')}</div><button class="primary" data-action="memory-start">Новый раунд</button><small>Рекорд: ${state.gameScores.memory||0}</small></div>`:`<div class="game-card"><h2>Счёт в уме</h2><div class="math-question">${state.ui.mathA??3} + ${state.ui.mathB??4} = ?</div><form data-form="math-game"><input class="answer-input" name="answer" type="number" placeholder="Ответ" required><button class="primary">Проверить</button></form><small>Рекорд: ${state.gameScores.math||0}</small></div>`}${section('Рекорды')}${Object.entries(state.gameScores).map(([k,v])=>`<div class="history-row">${esc(k)} · ${v}</div>`).join('')||empty('Сыграйте, чтобы сохранить рекорд')}`;}
function renderHelp(){const details=[['Жесты','Свайп вниз слева сверху: уведомления. Свайп вниз справа сверху: центр управления. Свайп вверх снизу в приложении: рабочий стол. Горизонтальный свайп на доме: соседняя страница.'],['HyperIsland','Таймер, музыка и демонстрационная запись экрана создают активность после соответствующего действия в симуляции. Нажмите на остров для подробностей.'],['Хранилище','Настройки, контакты, заметки, события, вкладки и переключатели сохраняются в localStorage. Медиафайлы хранятся в IndexedDB.'],['Браузер','Реальные URL открываются во встроенном iframe, если это разрешает сайт. CSP и X-Frame-Options могут блокировать встраивание. Используйте открытие отдельной вкладки.'],['Разрешения','Камера и микрофон требуют реального разрешения браузера. Звонки, SMS, батарея, сеть, фонарик и антивирусное сканирование не управляются как системные функции.'],['Известные ограничения','Это веб-приложение, не Android и не системная прошивка Xiaomi. Оно не устанавливает APK и не получает полный доступ к файловой системе.']];return `<div class="help-hero glass"><b>Справка HyperOS 4</b><small>Веб-симуляция, не прошивка</small></div>${details.map(([h,b])=>`<details class="help-detail"><summary>${h}</summary><p>${b}</p></details>`).join('')}${section('Самопроверка')}<div class="selfcheck-row"><span>localStorage</span><b>API найден</b></div><div class="selfcheck-row"><span>IndexedDB</span><b>${'indexedDB'in window?'API найден':'Недоступно'}</b></div><div class="selfcheck-row"><span>Медиафайлы</span><b>${state.media.length}</b></div><div class="selfcheck-row"><span>Приложений</span><b>${state.installed.length} из ${APPS.length}</b></div>`;}
function renderUpdate(){return `<div class="update-hero glass"><div class="update-orbit">↻</div><h2>HyperOS 4</h2><p>Interactive Web Simulation</p><small>Версия проекта: 0.1.0</small><span class="installed-pill">Это не прошивка Xiaomi</span></div>${section('Обновление проекта')}<div class="form-card"><p>Проверка версии демонстрационная: загрузка прошивки Xiaomi не выполняется.</p><button class="primary wide-button" data-action="check-update">Проверить обновления</button><div class="download-progress"><span style="width:${state.ui.progress||0}%"></span></div><small>${state.ui.progress>=100?'Уже используется последняя локальная версия':state.ui.progress?`Проверка ${state.ui.progress}%`:'Сборка: 22 октября 2026'}</small></div>${section('История изменений')}${['0.1.0 · Базовая оболочка и 27 приложений','Единое хранилище состояния и локальные медиа','Системные панели, жесты и HyperIsland','Реальная веб-навигация с ограничениями iframe'].map(x=>`<div class="changelog-row">✓ ${x}</div>`).join('')}`;}

function setSetting(key,value){if(key==='healthGoal'){state.healthGoal=Number(value);return;}if(['brightness','volume','iconScale','textScale','wallpaper'].includes(key)){state.settings[key]=Number(value);if(key==='wallpaper')state.settings.wallpaper=Math.max(0,Math.min(WALLPAPERS.length-1,state.settings.wallpaper));}if(key==='dark'){state.settings.dark=!!value;state.toggles.dark=!!value;}if(key==='animations')state.settings.animations=!!value;saveSoon();}
function navigate(raw){let url=(raw||'').trim();if(!url)return;if(!/^https?:\/\//i.test(url)){url=(/\s/.test(url)||!url.includes('.'))?`https://www.google.com/search?q=${encodeURIComponent(url)}`:`https://${url}`;}const tab=state.browserTabs.find(t=>t.id===state.activeTabId)||state.browserTabs[0];const nt={...tab,url,history:[...tab.history.slice(0,tab.index+1),url],index:tab.index+1};state.browserTabs=state.browserTabs.map(t=>t.id===tab.id?nt:t);state.browserHistory=[url,...state.browserHistory.filter(x=>x!==url)].slice(0,100);state.ui.browserUrl=url;state.ui.section='';saveSoon();render();}
function createFolder(appId,name){const f={id:makeId(),name:name.trim()||'Папка',appIds:[appId]};state.folders.push(f);state.desktopItems=state.desktopItems.filter(x=>x!==appId);state.desktopItems.push(`folder:${f.id}`);state.folderModal=null;state.contextMenu=null;saveSoon();render();toast('Папка создана');}
function closeAppScreen(){if(state.ui.section){state.ui.section='';render();}else goHome();}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;}if(cameraRecorder&&cameraRecorder.state!=='inactive'){try{cameraRecorder.stop();}catch{}}}
function stopMic(){if(micRecorder&&micRecorder.state!=='inactive'){try{micRecorder.stop();}catch{}}if(micStream){micStream.getTracks().forEach(t=>t.stop());micStream=null;}if(micTimer){clearInterval(micTimer);micTimer=null;}}
async function startCamera(){if(state.settings.notifyByApp['perm:camera']===false){state.ui.cameraStatus='denied';render();toast('Разрешение камеры отключено в Безопасности');return;}state.ui.cameraStatus='pending';render();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('getUserMedia недоступен');cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:state.ui.cameraFacing||'environment'},audio:state.ui.cameraMode==='video'});state.ui.cameraStatus='live';render();const v=$('#camera-feed');if(v){v.srcObject=cameraStream;await v.play().catch(()=>{});}toast('Камера подключена');}catch(e){state.ui.cameraStatus='denied';render();toast('Доступ к камере не предоставлен или недоступен');}}
async function capturePhoto(){if(state.ui.cameraMode==='video'){if(!cameraStream){toast('Сначала подключите камеру');return;}if(cameraRecorder&&cameraRecorder.state==='recording'){cameraRecorder.stop();return;}try{cameraChunks=[];cameraRecorder=new MediaRecorder(cameraStream);cameraRecorder.ondataavailable=e=>{if(e.data.size)cameraChunks.push(e.data);};cameraRecorder.onstop=async()=>{const blob=new Blob(cameraChunks,{type:cameraRecorder.mimeType||'video/webm'});if(blob.size)await saveMedia(blob,`VID_${Date.now()}.webm`,'video');state.ui.cameraRecording=false;};cameraRecorder.start();state.ui.cameraRecording=true;toast('Запись видео началась');render();}catch{toast('Запись видео не поддерживается этим браузером');}return;}
 if(!cameraStream||!$('#camera-feed')||!$('#camera-feed').videoWidth){state.ui.cameraStatus='demo';render();toast('Демо-режим: фото не создано, поскольку камера недоступна.');return;}const video=$('#camera-feed'),canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(async blob=>{if(blob)await saveMedia(blob,`IMG_${new Date().toISOString().replace(/[:.]/g,'-')}.jpg`,'image');},'image/jpeg',.9);}
async function startRecorder(){if(state.settings.notifyByApp['perm:microphone']===false){state.recorderStatus='denied';render();toast('Разрешение микрофона отключено');return;}try{micStream=await navigator.mediaDevices.getUserMedia({audio:true});micChunks=[];micRecorder=new MediaRecorder(micStream);micRecorder.ondataavailable=e=>{if(e.data.size)micChunks.push(e.data);};micRecorder.onstop=async()=>{const blob=new Blob(micChunks,{type:micRecorder.mimeType||'audio/webm'});if(blob.size)await saveMedia(blob,`REC_${Date.now()}.webm`,'recording');micStream?.getTracks().forEach(t=>t.stop());micStream=null;state.recorderStatus='idle';if(micTimer)clearInterval(micTimer);micElapsed=0;addNotice('recorder','Запись сохранена','Аудиофайл добавлен в библиотеку прототипа.');render();};micRecorder.start();state.recorderStatus='recording';micElapsed=0;micTimer=setInterval(()=>{micElapsed++;const el=$('.recorder-timer');if(el)el.textContent=fmtSeconds(micElapsed);},1000);render();toast('Идёт запись');}catch{state.recorderStatus='denied';render();toast('Доступ к микрофону не предоставлен');}}
function resetData(){if(!confirm('Сбросить сохранённые настройки, контакты, переписки, события и медиафайлы прототипа?'))return;clearMedia().then(()=>{state=defaults();persist();render();toast('Данные прототипа сброшены');});}

root.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;if(el.hasAttribute('data-stop'))return;
 const action=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
 switch(action){
 case 'open-app':openApp(id);break;case 'home':goHome();break;case 'back':closeAppScreen();break;case 'unlock':state.locked=false;state.pinMode=false;state.pinEntry='';render();toast('Экран разблокирован');break;case 'pin-open':state.pinMode=true;render();break;case 'pin-cancel':state.pinMode=false;state.pinEntry='';render();break;case 'pin-key':if(value==='⌫')state.pinEntry=state.pinEntry.slice(0,-1);else if(value==='✓'){if(state.pinEntry===state.settings.pin){state.locked=false;state.pinMode=false;state.pinEntry='';toast('Экран разблокирован');}else{state.pinEntry='';toast('Неверный PIN-код');}}else state.pinEntry=(state.pinEntry+value).slice(0,4);render();break;
 case 'page':state.page=Number(value)||0;render();break;case 'open-panel':state.panel=value;render();break;case 'status-tap':{const x=e.clientX;state.panel=x<window.innerWidth/2?'shade':'control';render();break;}case 'close-panel':state.panel='none';render();break;case 'toggle':toggle(id);break;case 'setting-toggle':if(id.startsWith('notify:')){const app=id.slice(7);state.settings.notifyByApp[app]=state.settings.notifyByApp[app]===false?true:false;}else if(id.startsWith('perm:')){state.settings.notifyByApp[id]=state.settings.notifyByApp[id]===false?true:false;}else if(id.startsWith('alarm:')){const aid=id.slice(6);state.alarms=state.alarms.map(a=>a.id===aid?{...a,enabled:!a.enabled}:a);}else if(id==='dark'||id==='animations'){setSetting(id,!state.settings[id]);}else toggle(id);saveSoon();render();break;
 case 'island':state.panel=state.panel==='island'?'none':'island';render();break;case 'edit-tiles':state.panel='editTiles';render();break;case 'tile-visibility':{const hidden=state.settings.hiddenTiles||[];state.settings.hiddenTiles=hidden.includes(id)?hidden.filter(k=>k!==id):[...hidden,id];saveSoon();render();break;}case 'read-all':state.notifications=state.notifications.map(n=>({...n,read:true}));saveSoon();render();break;case 'clear-notices':state.notifications=[];saveSoon();render();break;case 'remove-notice':state.notifications=state.notifications.filter(n=>n.id!==id);saveSoon();render();break;case 'notification-open':{const n=state.notifications.find(n=>n.id===id);if(n){n.read=true;const target=n.appId;state.panel='none';saveSoon();openApp(target);}break;}case 'clear-recents':state.recents=[];state.panel='none';saveSoon();render();break;
 case 'open-folder':state.folderViewer=id;render();break;case 'close-folder':if(e.target===el||el.matches('button')){state.folderViewer=null;render();}break;case 'folder-open-app':state.folderViewer=null;openApp(id);break;case 'close-folder-modal':state.folderModal=null;render();break;case 'folder-modal':state.folderModal={appId:id,value:''};state.contextMenu=null;render();break;case 'create-folder':createFolder(state.folderModal?.appId||'notes',$('#folder-name')?.value||'Папка');break;case 'remove-desktop':state.desktopItems=state.desktopItems.filter(x=>x!==id);state.contextMenu=null;saveSoon();render();toast('Убрано с рабочего стола; данные приложения сохранены');break;case 'close-context':if(e.target===el){state.contextMenu=null;render();}break;case 'rename-folder':{const f=state.folders.find(x=>x.id===id);const name=prompt('Новое название папки',f?.name||'Папка');if(f&&name?.trim())f.name=name.trim();state.contextMenu=null;saveSoon();render();break;}case 'delete-folder':{const f=state.folders.find(x=>x.id===id);state.folders=state.folders.filter(x=>x.id!==id);state.desktopItems=state.desktopItems.filter(x=>x!==`folder:${id}`);if(f)state.desktopItems.push(...f.appIds);state.contextMenu=null;saveSoon();render();break;}
 case 'section':state.ui.section=value||'';if(value==='new-contact'){state.ui.contactEdit=null;state.ui.contactDraft={name:'',phone:'',email:''};}if(value==='compose'){state.ui.mailTo='';state.ui.mailSubject='';state.ui.mailBody='';}render();break;case 'section-new-message':state.ui.section='new-message';render();break;case 'clear-query':state.ui.query='';render();break;case 'edit-contact':{const c=state.contacts.find(c=>c.id===id);if(c){state.ui.contactEdit=id;state.ui.contactDraft={...c};state.ui.section='new-contact';render();}break;}case 'delete-contact':{const old=state.contacts.find(c=>c.id===id);state.contacts=state.contacts.filter(c=>c.id!==id);if(old)state.messages=state.messages.filter(m=>m.phone!==old.phone);saveSoon();render();break;}case 'favorite-contact':state.contacts=state.contacts.map(c=>c.id===id?{...c,favorite:!c.favorite}:c);saveSoon();render();break;case 'dial':state.ui.number+=value;render();break;case 'dial-delete':state.ui.number=state.ui.number.slice(0,-1);render();break;case 'dial-clear':state.ui.number='';render();break;case 'call-number':state.ui.number=id;state.ui.section='';render();break;case 'call':if(!state.ui.number.trim()){toast('Введите номер');break;}state.calls.unshift({id:makeId(),number:state.ui.number,type:'outgoing',at:Date.now()});addNotice('phone','Исходящий вызов',`Имитация вызова на ${state.ui.number}. Реальный звонок не выполнялся.`);state.ui.number='';saveSoon();render();toast('Вызов имитирован');break;case 'open-thread':state.ui.activeThread=id;state.ui.section='thread';render();break;
 case 'new-tab':{const tab={id:makeId(),url:'https://example.com',history:['https://example.com'],index:0};state.browserTabs.push(tab);state.activeTabId=tab.id;state.ui.browserUrl=tab.url;state.ui.section='';saveSoon();render();break;}case 'switch-tab':state.activeTabId=id;state.ui.section='';state.ui.browserUrl=state.browserTabs.find(t=>t.id===id)?.url||'https://example.com';render();break;case 'close-tab':state.browserTabs=state.browserTabs.filter(t=>t.id!==id);if(!state.browserTabs.length){const t={id:makeId(),url:'https://example.com',history:['https://example.com'],index:0};state.browserTabs=[t];state.activeTabId=t.id;}else if(state.activeTabId===id)state.activeTabId=state.browserTabs[0].id;state.ui.section='';state.ui.browserUrl=state.browserTabs.find(t=>t.id===state.activeTabId)?.url;saveSoon();render();break;case 'navigate':navigate(value);break;case 'browser-back':case 'browser-forward':{const t=state.browserTabs.find(t=>t.id===state.activeTabId);if(t){t.index=Math.max(0,Math.min(t.history.length-1,t.index+(action==='browser-back'?-1:1)));t.url=t.history[t.index];state.ui.browserUrl=t.url;state.ui.section='';saveSoon();render();}break;}case 'bookmark':{const tab=state.browserTabs.find(t=>t.id===state.activeTabId);if(tab&&!state.bookmarks.includes(tab.url))state.bookmarks.unshift(tab.url);saveSoon();render();toast('Добавлено в закладки');break;}case 'copy-url':{const url=state.browserTabs.find(t=>t.id===state.activeTabId)?.url||'';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('URL скопирован')).catch(()=>toast(url));else toast(url);break;}
 case 'launch-camera':state.locked=false;openApp('camera');break;case 'retry-weather':weatherCache=null;weatherLastCity='';weatherError='';weatherLoading=false;loadWeather(state.ui.city||'Moscow');break;case 'open-weather':state.locked=false;state.ui.section='';openApp('weather');break;case 'quick-lock':state.toggles.flashlight=!state.toggles.flashlight;render();toast('Фонарик имитируется в прототипе');break;case 'camera-start':startCamera();break;case 'camera-demo':state.ui.cameraStatus='demo';render();toast('Демо-режим: настоящее фото не создаётся');break;case 'camera-mode':state.ui.cameraMode=value;if(cameraStream)stopCamera();state.ui.cameraStatus='idle';render();break;case 'camera-flip':state.ui.cameraFacing=state.ui.cameraFacing==='user'?'environment':'user';if(cameraStream)startCamera();else render();break;case 'capture':capturePhoto();break;
 case 'view-media':state.viewerId=id;render();break;case 'close-viewer':if(e.target===el||el.tagName==='BUTTON'){state.viewerId=null;render();}break;case 'delete-media':deleteMedia(id);break;case 'toggle-audio':{const audio=$(`[data-audio="${id}"]`);if(audio){if(state.playingMediaId===id&&!audio.paused){audio.pause();}else{state.playingMediaId=id;audio.play().catch(()=>toast('Браузер не смог воспроизвести файл'));state.mediaPlaying=true;updateIslandOnly();saveSoon();}}break;}case 'pause-music':{const a=$(`[data-audio="${state.playingMediaId}"]`);if(a&&!a.paused)a.pause();state.mediaPlaying=false;saveSoon();render();break;}
 case 'wallpaper':state.settings.wallpaper=Number(value);saveSoon();render();break;case 'accent':state.settings.accent=value;saveSoon();render();break;case 'install-app':{const a=id;if(state.installed.includes(a)){state.installed=state.installed.filter(x=>x!==a);state.desktopItems=state.desktopItems.filter(x=>x!==a);toast('Приложение скрыто из установленного списка');}else{state.installed.push(a);if(!dockIds.includes(a)&&!state.desktopItems.includes(a))state.desktopItems.push(a);toast('Приложение добавлено в симуляцию');}saveSoon();render();break;}case 'clock-style':state.settings.lockClock=(state.settings.lockClock+1)%3;saveSoon();render();break;case 'change-pin':{const v=prompt('Введите новый PIN прототипа (4 цифры)',state.settings.pin);if(v&&/^\d{4}$/.test(v)){state.settings.pin=v;toast('PIN изменён');saveSoon();}else if(v)toast('PIN должен содержать ровно 4 цифры');break;}case 'show-gestures':toast('Свайп вниз слева: уведомления · справа: центр управления · вверх снизу: домой · горизонтально на рабочем столе: страницы');break;case 'reset':resetData();break;case 'toast':toast(value);break;
 case 'start-timer':{const secs=Math.max(1,Math.min(86400,Number(state.ui.timerInput)||60));state.timerDuration=secs;state.timerEndsAt=Date.now()+secs*1000;state.ui.section='';addNotice('clock','Таймер запущен',`Установлено ${secs} секунд.`);saveSoon();render();toast('Таймер добавлен в HyperIsland');break;}case 'stop-timer':state.timerEndsAt=null;saveSoon();render();break;case 'toggle-stopwatch':if(state.stopwatchRunningAt){state.stopwatchElapsed+=Date.now()-state.stopwatchRunningAt;state.stopwatchRunningAt=null;}else state.stopwatchRunningAt=Date.now();saveSoon();render();break;case 'reset-stopwatch':state.stopwatchElapsed=0;state.stopwatchRunningAt=null;saveSoon();render();break;case 'delete-alarm':state.alarms=state.alarms.filter(a=>a.id!==id);saveSoon();render();break;case 'calendar-date':state.ui.eventDate=value;render();break;case 'edit-event':{const ev=state.events.find(x=>x.id===id);if(ev){state.ui.eventTitle=ev.title;state.ui.eventDate=ev.date;state.ui.eventTime=ev.time;state.events=state.events.filter(x=>x.id!==id);render();}break;}case 'delete-event':state.events=state.events.filter(x=>x.id!==id);saveSoon();render();break;case 'calc-key':{const v=value;const u=state.ui;if(v==='C'){u.calculatorExpr='';u.calculatorResult='';}else if(v==='⌫')u.calculatorExpr=u.calculatorExpr.slice(0,-1);else if(v==='='){try{const result=calc(u.calculatorExpr);u.calculatorResult=result;state.calcHistory=state.calcHistory||[];state.calcHistory.push(`${u.calculatorExpr} = ${result}`);state.calcHistory=state.calcHistory.slice(-30);}catch(err){u.calculatorResult=err.message||'Ошибка';}}else if(v==='±')u.calculatorExpr=u.calculatorExpr.startsWith('-')?u.calculatorExpr.slice(1):'-'+u.calculatorExpr;else u.calculatorExpr+=v;saveSoon();render();break;}case 'clear-calc-history':state.calcHistory=[];saveSoon();render();break;
 case 'new-note':{const n={id:makeId(),title:'Новая заметка',body:'',pinned:false,color:['#fff1a8','#d8ebff','#fdd9e6','#d6f2dc'][state.notes.length%4],updatedAt:Date.now()};state.notes.unshift(n);state.ui.selected=n.id;state.ui.query='';saveSoon();render();break;}case 'select-note':state.ui.selected=id;render();break;case 'pin-note':state.notes=state.notes.map(n=>n.id===id?{...n,pinned:!n.pinned,updatedAt:Date.now()}:n);saveSoon();render();break;case 'delete-note':state.notes=state.notes.filter(n=>n.id!==id);state.ui.selected='';saveSoon();render();break;case 'file-filter':state.ui.fileFilter=value;render();break;case 'open-files-folder':state.ui.fileFolder=id;render();break;case 'folder-up':state.ui.fileFolder=state.filesFolders.find(f=>f.id===state.ui.fileFolder)?.parent||null;render();break;case 'delete-files-folder':state.filesFolders=state.filesFolders.filter(f=>f.id!==id&&f.parent!==id);saveSoon();render();break;case 'delete-download':state.downloads=state.downloads.filter(d=>d.id!==id);saveSoon();render();break;case 'delete-mail':state.mailDrafts=state.mailDrafts.filter(m=>m.id!==id);saveSoon();render();break;
 case 'search-history':state.ui.query=value;render();break;case 'game-select':state.ui.game=value;state.ui.gameScore=0;render();break;case 'game-tap':state.ui.gameScore=(state.ui.gameScore||0)+1;state.gameScores.tap=Math.max(state.gameScores.tap||0,state.ui.gameScore);saveSoon();render();break;case 'memory-start':state.ui.memoryTarget=1+Math.floor(Math.random()*4);render();break;case 'memory-answer':{const good=Number(value)===Number(state.ui.memoryTarget??3);if(good){state.gameScores.memory=Math.max(state.gameScores.memory||0,1);toast('Верно! Очко сохранено.');}else toast('Не угадали. Попробуйте новый раунд.');state.ui.memoryTarget=1+Math.floor(Math.random()*4);saveSoon();render();break;}case 'check-update':state.ui.progress=0;render();const timer=setInterval(()=>{state.ui.progress=Math.min(100,(state.ui.progress||0)+20);saveSoon();if(state.ui.progress>=100){clearInterval(timer);addNotice('update','Проверка завершена','Установлена актуальная локальная версия 0.1.0.');}if(state.currentApp==='update')render();},180);break;
 default:break;
 }
});

root.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=new FormData(form),type=form.dataset.form;
 switch(type){case 'contact':{const name=String(data.get('name')||'').trim(),phone=String(data.get('phone')||'').trim(),email=String(data.get('email')||'').trim();if(!name){toast('Введите имя контакта');return;}if(state.ui.contactEdit){const c=state.contacts.find(c=>c.id===state.ui.contactEdit);if(c)Object.assign(c,{name,phone,email});}else state.contacts.unshift({id:makeId(),name,phone,email,favorite:false});state.ui.section='';state.ui.contactEdit=null;state.ui.contactDraft=null;saveSoon();render();toast('Контакт сохранён');break;}
 case 'message':{const text=String(data.get('text')||'').trim(),thread=state.messages.find(m=>m.id===state.ui.activeThread);if(thread&&text)thread.messages.push({id:makeId(),from:'me',text,at:Date.now()});addNotice('messages','Сообщение добавлено','Переписка изменена локально, SMS не отправлялось.');state.ui.msgText='';saveSoon();render();break;}
 case 'new-message':{const recipient=String(data.get('recipient')||'').trim(),text=String(data.get('text')||'').trim();if(!recipient||!text)return;const c=state.contacts.find(c=>c.phone===recipient||c.name.toLowerCase()===recipient.toLowerCase());const thread={id:makeId(),contactName:c?.name||recipient,phone:c?.phone||recipient,messages:[{id:makeId(),from:'me',text,at:Date.now()}]};state.messages.unshift(thread);state.ui.section='';saveSoon();render();toast('Создан локальный диалог');break;}
 case 'browser':navigate(String(data.get('url')||''));break;
 case 'event':{const title=String(data.get('title')||'').trim();if(!title)return;state.events.push({id:makeId(),title,date:String(data.get('date')||todayISO()),time:String(data.get('time')||'12:00')});state.events.sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));state.ui.eventTitle='';saveSoon();render();toast('Событие создано');break;}
 case 'alarm':state.alarms.push({id:makeId(),time:String(data.get('time')||'07:30'),label:String(data.get('label')||'Будильник'),enabled:true});saveSoon();render();toast('Будильник сохранён');break;
 case 'weather':{const city=String(data.get('city')||'Moscow').trim()||'Moscow';state.ui.city=city;weatherCache=null;weatherLastCity='';weatherError='';saveSoon();await loadWeather(city);break;}
 case 'file-folder':{const name=String(data.get('name')||'').trim();if(!name)return;state.filesFolders.push({id:makeId(),name,parent:state.ui.fileFolder,createdAt:Date.now()});state.ui.newFolderName='';state.ui.section='';saveSoon();render();break;}
 case 'mail':state.mailDrafts.unshift({id:makeId(),to:String(data.get('to')||''),subject:String(data.get('subject')||''),body:String(data.get('body')||''),sent:false,at:Date.now()});state.ui.section='';saveSoon();render();toast('Черновик сохранён. Письмо не отправлялось.');break;
 case 'math-game':{const answer=Number(data.get('answer'));const good=answer===Number(state.ui.mathA??3)+Number(state.ui.mathB??4);if(good){state.gameScores.math=Math.max(state.gameScores.math||0,(state.gameScores.math||0)+1);toast('Верно!');}else toast(`Ответ: ${Number(state.ui.mathA??3)+Number(state.ui.mathB??4)}`);state.ui.mathA=1+Math.floor(Math.random()*12);state.ui.mathB=1+Math.floor(Math.random()*12);saveSoon();render();break;}
 }
});

root.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-search]')){state.ui.query=el.value;const pos=el.selectionStart;saveSoon();render();const fresh=$('[data-search]');if(fresh){fresh.focus();fresh.setSelectionRange(pos,pos);}return;}
 if(el.matches('[data-ui]')){state.ui[el.dataset.ui]=el.value;return;}
 if(el.matches('[data-setting]')){setSetting(el.dataset.setting,el.type==='checkbox'?el.checked:Number(el.value));const b=el.parentElement.querySelector('b');if(b){const k=el.dataset.setting;b.textContent=k==='textScale'||k==='iconScale'?Math.round(Number(el.value)*100)+'%':String(el.value)+'%';}const rootEl=$('.os-root');if(rootEl){rootEl.classList.toggle('dark',state.settings.dark);document.body.classList.toggle('dark',state.settings.dark);const overlay=$('.brightness-overlay',rootEl);if(overlay&&el.dataset.setting==='brightness')overlay.style.opacity=Math.max(0,(100-state.settings.brightness)/100)*.55;}
 saveSoon();return;}
 if(el.matches('[data-note-title]')||el.matches('[data-note-body]')){const note=state.notes.find(n=>n.id===el.dataset.noteTitle||n.id===el.dataset.noteBody);if(note){if(el.matches('[data-note-title]'))note.title=el.value;else note.body=el.value;note.updatedAt=Date.now();saveSoon();}return;}
 if(el.matches('#folder-name')){if(state.folderModal)state.folderModal.value=el.value;return;}
});
root.addEventListener('change',async e=>{const el=e.target;if(el.matches('[data-import]')){const kind=el.dataset.import;const files=[...el.files];for(const file of files)await saveMedia(file,file.name,kind);el.value='';return;}if(el.matches('[data-setting]')){setSetting(el.dataset.setting,el.type==='checkbox'?el.checked:Number(el.value));persist();render();return;}});
root.addEventListener('play',e=>{const el=e.target;if(el.matches('audio[data-audio]')){state.playingMediaId=el.dataset.audio;state.mediaPlaying=true;saveSoon();updateIslandOnly();}},true);
root.addEventListener('pause',e=>{const el=e.target;if(el.matches('audio[data-audio]')&&state.playingMediaId===el.dataset.audio){state.mediaPlaying=false;saveSoon();updateIslandOnly();}},true);
function updateIslandOnly(){const island=$('.hyper-island');const old=state.panel;if(!island)return;const parent=island.parentElement;const temp=document.createElement('div');temp.innerHTML=hyperIsland();island.replaceWith(temp.firstElementChild);}
root.addEventListener('contextmenu',e=>{const target=e.target.closest('[data-context]');if(!target||state.locked||state.currentApp)return;e.preventDefault();const spec=target.dataset.context.split(':');state.contextMenu={kind:spec[0],id:spec.slice(1).join(':'),x:Math.min(e.clientX,window.innerWidth-205),y:Math.min(e.clientY,window.innerHeight-200)};render();});
root.addEventListener('touchstart',e=>{const t=e.touches[0];lastTouch={x:t.clientX,y:t.clientY,time:Date.now(),target:e.target};const context=e.target.closest('[data-context]');if(context){clearTimeout(root._longPress);root._longPress=setTimeout(()=>{const sp=context.dataset.context.split(':');state.contextMenu={kind:sp[0],id:sp.slice(1).join(':'),x:Math.min(t.clientX,window.innerWidth-205),y:Math.min(t.clientY,window.innerHeight-200)};render();},620);}}, {passive:true});
root.addEventListener('touchmove',()=>clearTimeout(root._longPress),{passive:true});
root.addEventListener('touchend',e=>{clearTimeout(root._longPress);if(!lastTouch)return;const st=lastTouch,t=e.changedTouches[0],dx=t.clientX-st.x,dy=t.clientY-st.y,h=window.innerHeight,w=window.innerWidth;lastTouch=null;const target=st.target;if(target?.closest?.('input,textarea,select,button,[data-no-swipe],iframe,video,audio'))return;
 if(state.locked){if(dy<-45&&st.y>h*.35){state.locked=false;state.pinMode=false;state.pinEntry='';render();toast('Экран разблокирован');}return;}
 if(state.panel!=='none'){if(dy<-55){state.panel='none';render();}return;}
 if(st.y<42&&dy>55){state.panel=st.x<w/2?'shade':'control';render();return;}
 if(state.currentApp&&dy<-75&&st.y>h-125){goHome();return;}
 if(!state.currentApp&&Math.abs(dx)>62&&Math.abs(dx)>Math.abs(dy)*1.15){const n=Math.max(1,Math.ceil(state.desktopItems.length/16));state.page=Math.max(0,Math.min(n-1,state.page+(dx<0?1:-1)));render();return;}
 },{passive:true});

function updateClocks(){const now=Date.now();$$('[data-clock]').forEach(el=>el.textContent=fmtTime(now));const seconds=$('[data-clock-seconds]');if(seconds)seconds.textContent=new Date(now).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'});const sw=$('#stopwatch-display');if(sw)sw.textContent=fmtStopwatch(state.stopwatchElapsed+(state.stopwatchRunningAt?now-state.stopwatchRunningAt:0));const tr=$('#timer-remain');if(tr&&state.timerEndsAt)tr.textContent=fmtRemaining(state.timerEndsAt-now);const ct=$('#clock-timer');if(ct&&state.timerEndsAt)ct.textContent=fmtRemaining(state.timerEndsAt-now);
 if(state.timerEndsAt&&state.timerEndsAt<=now){state.timerEndsAt=null;addNotice('clock','Таймер завершён','Время вышло.');saveSoon();render();toast('Таймер завершён');}
 const min=new Date(now).toISOString().slice(0,16);if(min!==lastAlarmMinute){lastAlarmMinute=min;const time=fmtTime(now);const alarm=state.alarms.find(a=>a.enabled&&a.time===time);if(alarm){alarm.enabled=false;addNotice('clock',alarm.label||'Будильник','Сработал будильник симуляции.');saveSoon();render();toast('Будильник!');}}
}
setInterval(updateClocks,500);

// Lightweight offline shell. External websites and weather naturally require a network connection.
if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
loadMedia().then(()=>render()).catch(()=>render());
})();
